/* M.V.P. Accelerator, Player-Coach track: narration text and timing cues (round 3, Dennis). Generated by _generators/cues_r3.py. */
window.NARRATION = {"pc_n_G0": {"dur": 10.4, "text": "Hi, and welcome to the Arena. This part sets up your season as a Player-Coach. It takes about fifteen minutes, and you only do it once. Select Start when you're ready.", "sents": [[0, "Hi, and welcome to the Arena.", 0], [2.55, "This part sets up your season as a Player-Coach.", 1], [5.63, "It takes about fifteen minutes, and you only do it once.", 1], [8.79, "Select Start when you're ready.", 2]], "v": "r3", "cues": [0, 2.55, 8.79]}, "pc_n_G5": {"dur": 43.12, "text": "Let's set up your season. First comes your Benchmark Pre-Assessment. It takes about ten minutes, and it opens on the next screen. Next, download your Player-Coach Playbook. Every lesson gives you your practice for the week, including one conversation to hold with your Athleader. Then get the Starting Line agenda. It's the first thirty-minute conversation with your Athleader, and you're the one who books it, ideally this week. Last, block about an hour a week: your lesson, then one core rep, which is often a conversation you'd hold anyway. Pick Google Calendar or Outlook and it goes straight into your calendar, or use the other option for Apple and anything else. Move it when you need to, as long as you keep it. Select Next when you're ready to start your pre-assessment.", "sents": [[0.01, "Let's set up your season.", 0], [1.69, "First comes your Benchmark Pre-Assessment.", 1], [4.33, "It takes about ten minutes, and it opens on the next screen.", 1], [7.65, "Next, download your Player-Coach Playbook.", 2], [10.61, "Every lesson gives you your practice for the week, including one conversation to hold with your Athleader.", 2], [15.95, "Then get the Starting Line agenda.", 3], [18.25, "It's the first thirty-minute conversation with your Athleader, and you're the one who books it, ideally this week.", 3], [23.65, "Last, block about an hour a week: your lesson, then one core rep, which is often a conversation you'd hold anyway.", 4], [30.99, "Pick Google Calendar or Outlook and it goes straight into your calendar, or use the other option for Apple and anything else.", 4], [37.49, "Move it when you need to, as long as you keep it.", 4], [40.23, "Select Next when you're ready to start your pre-assessment.", 5]], "v": "r3", "cues": [0.01, 1.69, 7.65, 15.95, 23.65, 40.23]}, "pc_n_G9": {"dur": 57.04, "text": "Every lesson follows the same steps, so you'll always know where you are. It opens with a coaching moment you'll probably recognize. Then a quick check-in, where you notice what went on in you. Only you see what you write. Next come four short videos with Melissa. The first sets up the lesson, the second is about leading yourself, and the last two are about coaching your Athleader and your team. You make a call on a real situation, then run a short drill that puts you under a little pressure. The practice happens during the week, starting with one core rep. Part of your job this season is creating space to practice: low-risk moments where your team can take a risk and build confidence. Practice yourself too, and ask for feedback on how it's landing. Each lesson also brings in an Athleader Pro, with a three-minute drill of their own. A quick Pulse Check after every lesson tracks how you're changing across the season, and a short knowledge check covers the main ideas before you close the lesson.", "sents": [[0, "Every lesson follows the same steps, so you'll always know where you are.", 0], [4.45, "It opens with a coaching moment you'll probably recognize.", 1], [7.83, "Then a quick check-in, where you notice what went on in you.", 1], [11.39, "Only you see what you write.", 1], [13.37, "Next come four short videos with Melissa.", 2], [16.17, "The first sets up the lesson, the second is about leading yourself, and the last two are about coaching your Athleader and your team.", 2], [23.65, "You make a call on a real situation, then run a short drill that puts you under a little pressure.", 2], [29.23, "The practice happens during the week, starting with one core rep.", 3], [33.07, "Part of your job this season is creating space to practice: low-risk moments where your team can take a risk and build confidence.", 3], [40.59, "Practice yourself too, and ask for feedback on how it's landing.", 3], [44.31, "Each lesson also brings in an Athleader Pro, with a three-minute drill of their own.", 3], [48.97, "A quick Pulse Check after every lesson tracks how you're changing across the season, and a short knowledge check covers the main ideas before you close the lesson.", 4]], "v": "r3", "cues": [0, 4.45, 13.37, 29.23, 48.97]}, "pc_n_G10": {"dur": 14.72, "text": "Your starting point is recorded and Lesson 1 is open. Nice work getting set up. It starts with what a Player-Coach does, one tool for the whole season, and the first conversation you'll have with your Athleader. Select Open Lesson 1 when you're ready.", "sents": [[0.01, "Your starting point is recorded and Lesson 1 is open.", 0], [3.63, "Nice work getting set up.", 0], [5.53, "It starts with what a Player-Coach does, one tool for the whole season, and the first conversation you'll have with your Athleader.", 1], [12.63, "Select Open Lesson 1 when you're ready.", 1]], "v": "r3", "cues": [0.01, 5.53]}, "pc_n_1_0": {"dur": 11.28, "text": "Lesson 1 is about the role you're stepping into. You'll spend about forty minutes here. Your core rep this week is one thirty-minute conversation with your Athleader. Select Start lesson.", "sents": [[0, "Lesson 1 is about the role you're stepping into.", 0], [3.15, "You'll spend about forty minutes here.", 1], [5.35, "Your core rep this week is one thirty-minute conversation with your Athleader.", 1], [9.81, "Select Start lesson.", 1]], "v": "r3", "cues": [0, 3.15]}, "pc_n_1_1": {"dur": 13.2, "text": "Read this moment, and picture yourself in it. Most managers say something like this and mean it kindly. This season asks more of you, and the first thing it asks for is one conversation in the next week.", "sents": [[0, "Read this moment, and picture yourself in it.", 0], [3.43, "Most managers say something like this and mean it kindly.", 1], [7.17, "This season asks more of you, and the first thing it asks for is one conversation in the next week.", 1]], "v": "r3", "cues": [0, 3.43]}, "pc_n_1_4": {"dur": 30.16, "text": "Here's what you'll practice in this lesson. You're doing two things this season. You're working on your own leadership, and you're coaching your Athleader while they work on theirs. You'll name one pressure point you feel right now, and one wellbeing practice you'll start this week to handle it. You'll pick one place where your Athleader's growth would lift the whole team. Melissa calls this the Manager Multiplier Effect. And you'll hold your first conversation with your Athleader, the Starting Line. The Pulse Check at the end of the lesson asks whether it's booked.", "sents": [[0.03, "Here's what you'll practice in this lesson.", 0], [2.27, "You're doing two things this season.", 1], [4.39, "You're working on your own leadership, and you're coaching your Athleader while they work on theirs.", 1], [9.59, "You'll name one pressure point you feel right now, and one wellbeing practice you'll start this week to handle it.", 2], [15.71, "You'll pick one place where your Athleader's growth would lift the whole team.", 3], [19.77, "Melissa calls this the Manager Multiplier Effect.", 3], [22.77, "And you'll hold your first conversation with your Athleader, the Starting Line.", 4], [27.25, "The Pulse Check at the end of the lesson asks whether it's booked.", 4]], "v": "r3", "cues": [0.03, 2.27, 9.59, 15.71, 22.77]}, "pc_n_1_6": {"dur": 15.36, "text": "Melissa just asked you to name one leadership behavior you want to strengthen. Write it here, in one sentence. Make it something your team would notice if it changed. It's saved, and you'll see it again in Lesson 6. Then select Next to download your Playbook.", "sents": [[0, "Melissa just asked you to name one leadership behavior you want to strengthen.", 0], [4.43, "Write it here, in one sentence.", 1], [6.77, "Make it something your team would notice if it changed.", 1], [9.67, "It's saved, and you'll see it again in Lesson 6.", 1], [12.73, "Then select Next to download your Playbook.", 2]], "v": "r3", "cues": [0, 4.43, 12.73]}, "pc_n_1_7": {"dur": 10.64, "text": "Now download your Player-Coach Playbook, because every lesson uses it. It opens in a new tab. Save a copy somewhere you'll find it, and if you already saved it during setup, you're all set.", "sents": [[0, "Now download your Player-Coach Playbook, because every lesson uses it.", 0], [4.43, "It opens in a new tab.", 1], [5.99, "Save a copy somewhere you'll find it, and if you already saved it during setup, you're all set.", 1]], "v": "r3", "cues": [0, 4.43]}, "pc_n_1_9": {"dur": 32.56, "text": "Here's the shape of Melissa's story. She was running a business and caring for her family, and she was worn out. Her team felt it, and so did her family. She described it as surviving rather than leading. What changed things was treating her own wellbeing as fixed on the calendar, with recovery time she protected. Once she did that, she could lead her team through change again. The point for you as a Player-Coach is simple. Your team takes its steadiness from you, so looking after yourself comes first.", "sents": [[0.03, "Here's the shape of Melissa's story.", 0], [2.37, "She was running a business and caring for her family, and she was worn out.", 1], [7.25, "Her team felt it, and so did her family.", 1], [10.47, "She described it as surviving rather than leading.", 1], [14.01, "What changed things was treating her own wellbeing as fixed on the calendar, with recovery time she protected.", 2], [20.85, "Once she did that, she could lead her team through change again.", 3], [24.67, "The point for you as a Player-Coach is simple.", 4], [27.49, "Your team takes its steadiness from you, so looking after yourself comes first.", 4]], "v": "r3", "cues": [0.03, 2.37, 14.01, 20.85, 24.67]}, "pc_n_1_10": {"dur": 16.0, "text": "Agility, Resilience, Alignment and Wellbeing are the same four your Athleader is conditioning, so you'll share a language all season. Select each one to hear what changes when it's conditioned. As you listen, think about which one your team would say you're weakest on.", "sents": [[0.05, "Agility, Resilience, Alignment and Wellbeing are the same four your Athleader is conditioning, so you'll share a language all season.", 0], [8.87, "Select each one to hear what changes when it's conditioned.", 1], [12.09, "As you listen, think about which one your team would say you're weakest on.", 1]], "v": "r3", "cues": [0.05, 8.87]}, "pc_n_1_12": {"dur": 28.48, "text": "Melissa's example shows the multiplier at work. David managed Kim, and her presentation skills were holding her back. So he spent time coaching her before a big client pitch. Kim led the pitch and the team won the contract. Morale went up, and senior leaders noticed the whole team. That's the Manager Multiplier Effect: coach one person well, and the gain spreads through the team. In your Playbook this week, you'll name where that could happen with your Athleader.", "sents": [[0, "Melissa's example shows the multiplier at work.", 0], [3.51, "David managed Kim, and her presentation skills were holding her back.", 1], [7.71, "So he spent time coaching her before a big client pitch.", 2], [11.29, "Kim led the pitch and the team won the contract.", 3], [14.33, "Morale went up, and senior leaders noticed the whole team.", 3], [18.01, "That's the Manager Multiplier Effect: coach one person well, and the gain spreads through the team.", 4], [24.31, "In your Playbook this week, you'll name where that could happen with your Athleader.", 4]], "v": "r3", "cues": [0, 3.51, 7.71, 11.29, 18.01]}, "pc_n_1_14": {"dur": 33.04, "text": "This is the agenda for your first conversation. Melissa calls it the Starting Line, and it takes thirty minutes. Start by arriving. Five minutes to put the week down, so you're both actually in the room. Then name the win. Ask what will have changed ninety days from now, and answer it for yourself too. Next, get honest about what each of you tends to drop when things get busy, and say what you need from each other. Before you leave, book a recurring fifteen-minute check-in for the season. Open the agenda to see the full version, including the commitment you both sign.", "sents": [[0, "This is the agenda for your first conversation.", 0], [2.71, "Melissa calls it the Starting Line, and it takes thirty minutes.", 0], [6.57, "Start by arriving.", 1], [8.19, "Five minutes to put the week down, so you're both actually in the room.", 1], [11.89, "Then name the win.", 2], [13.73, "Ask what will have changed ninety days from now, and answer it for yourself too.", 2], [18.09, "Next, get honest about what each of you tends to drop when things get busy, and say what you need from each other.", 3], [24.77, "Before you leave, book a recurring fifteen-minute check-in for the season.", 4], [28.33, "Open the agenda to see the full version, including the commitment you both sign.", 4]], "v": "r3", "cues": [0, 6.57, 11.89, 18.09, 24.77]}, "pc_n_1_15": {"dur": 9.68, "text": "Let's put the Starting Line under a little pressure. Your Athleader is hesitant, and their answers stay general. Pick the move you'd make, and you'll hear where it leads.", "sents": [[0, "Let's put the Starting Line under a little pressure.", 0], [3.15, "Your Athleader is hesitant, and their answers stay general.", 1], [6.83, "Pick the move you'd make, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0, 3.15]}, "pc_n_1_15_o0": {"dur": 13.6, "text": "Offering your own ideas feels helpful, and it fills an awkward silence. The trouble is that they leave with your goals rather than theirs, and they learn it's safer to wait for you next time. Try the other option to compare.", "sents": [[0.03, "Offering your own ideas feels helpful, and it fills an awkward silence.", 0], [5.11, "The trouble is that they leave with your goals rather than theirs, and they learn it's safer to wait for you next time.", 0], [11.87, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.03]}, "pc_n_1_15_o1": {"dur": 11.36, "text": "That question is about them, and it has no wrong answer. Then you wait. The pause after it is usually where the real goal shows up, and you've shown them it's safe to say it.", "sents": [[0.05, "That question is about them, and it has no wrong answer.", 0], [4.11, "Then you wait.", 0], [5.73, "The pause after it is usually where the real goal shows up, and you've shown them it's safe to say it.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_1_16": {"dur": 27.44, "text": "Your core rep this week is the Starting Line, a thirty-minute conversation with your Athleader. Book it and hold it, using the agenda. If you have more time, start with your intention. Name the pressure point you feel now and the wellbeing practice you'll start. And write down where your Athleader's growth would lift the team. Be specific about the outcome. Run your core rep, then ask your Athleader how it landed. Select Open your Lesson 1 pages to get started.", "sents": [[0.01, "Your core rep this week is the Starting Line, a thirty-minute conversation with your Athleader.", 0], [5.79, "Book it and hold it, using the agenda.", 0], [8.69, "If you have more time, start with your intention.", 1], [11.53, "Name the pressure point you feel now and the wellbeing practice you'll start.", 1], [15.67, "And write down where your Athleader's growth would lift the team.", 2], [19.09, "Be specific about the outcome.", 2], [21.15, "Run your core rep, then ask your Athleader how it landed.", 3], [24.63, "Select Open your Lesson 1 pages to get started.", 3]], "v": "r3", "cues": [0.01, 8.69, 15.67, 21.15]}, "pc_n_1_17": {"dur": 10.08, "text": "Each lesson brings in an Athleader Pro, a leader who lives one part of this work. This time it's Tracey Newell, the Change Commander. Press play to hear from her.", "sents": [[0, "Each lesson brings in an Athleader Pro, a leader who lives one part of this work.", 0], [5.33, "This time it's Tracey Newell, the Change Commander.", 1], [8.67, "Press play to hear from her.", 1]], "v": "r3", "cues": [0, 5.33]}, "pc_n_1_18": {"dur": 11.68, "text": "Now try Tracey's drill. It takes three minutes. Select Start the timer and work through each step as it lights up. When you're done, or once you've planned when you'll run it, tick the box that fits.", "sents": [[0.05, "Now try Tracey's drill.", 0], [1.79, "It takes three minutes.", 0], [3.19, "Select Start the timer and work through each step as it lights up.", 1], [7.37, "When you're done, or once you've planned when you'll run it, tick the box that fits.", 1]], "v": "r3", "cues": [0.05, 3.19]}, "pc_n_1_20_q0": {"dur": 8.72, "text": "A few questions to check the main ideas. First: what does the Manager Multiplier Effect describe? Choose one, then select Submit.", "sents": [[0, "A few questions to check the main ideas.", 0], [2.47, "First: what does the Manager Multiplier Effect describe?", 0], [6.53, "Choose one, then select Submit.", 0]], "v": "r3", "cues": [0]}, "pc_n_1_20_w0": {"dur": 8.08, "text": "When you coach one person well, their better work and engagement carry across the team, the way Kim's pitch won the contract for everyone.", "sents": [[0.07, "When you coach one person well, their better work and engagement carry across the team, the way Kim's pitch won the contract for everyone.", 0]], "v": "r3", "cues": [0.07]}, "pc_n_1_20_q1": {"dur": 3.2, "text": "Why does leading yourself come before leading others?", "sents": [[0.05, "Why does leading yourself come before leading others?", 0]], "v": "r3", "cues": [0.05]}, "pc_n_1_20_w1": {"dur": 9.92, "text": "Melissa's own story makes the point. When she was running on empty, her team felt it. Looking after your own energy is what lets you be the anchor.", "sents": [[0.01, "Melissa's own story makes the point.", 0], [2.59, "When she was running on empty, her team felt it.", 0], [6.17, "Looking after your own energy is what lets you be the anchor.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_1_20_q2": {"dur": 6.48, "text": "In the Starting Line, your Athleader says, I'm not sure what I want from this yet. What's the best next move?", "sents": [[0, "In the Starting Line, your Athleader says, I'm not sure what I want from this yet.", 0], [5.03, "What's the best next move?", 0]], "v": "r3", "cues": [0]}, "pc_n_1_20_w2": {"dur": 9.92, "text": "An open question with no wrong answer, followed by a real pause, makes it safe for them to find their own goal. Suggesting goals hands them yours.", "sents": [[0.01, "An open question with no wrong answer, followed by a real pause, makes it safe for them to find their own goal.", 0], [7.47, "Suggesting goals hands them yours.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_1_20_q3": {"dur": 3.68, "text": "Last one. What should every Starting Line end with?", "sents": [[0, "Last one.", 0], [1.17, "What should every Starting Line end with?", 0]], "v": "r3", "cues": [0]}, "pc_n_1_20_w3": {"dur": 8.64, "text": "The rhythm is what carries the season. Book the fifteen-minute check-in before you leave the room, and the rest of the lessons have somewhere to land.", "sents": [[0.03, "The rhythm is what carries the season.", 0], [3.09, "Book the fifteen-minute check-in before you leave the room, and the rest of the lessons have somewhere to land.", 0]], "v": "r3", "cues": [0.03]}, "pc_n_1_21": {"dur": 34.16, "text": "Before you go, here's what to keep from this lesson. You have two roles this season. You're conditioning your own leadership, and you're coaching your Athleader through theirs. Looking after yourself comes first. When you coach one person well, the whole team gains. Your Playbook asks you to name where that could happen. And the Starting Line sets the rhythm for everything after it. Book it this week. Select Download my answers for a Word copy of what you wrote in this lesson. If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", "sents": [[0.03, "Before you go, here's what to keep from this lesson.", 0], [3.35, "You have two roles this season.", 1], [5.55, "You're conditioning your own leadership, and you're coaching your Athleader through theirs.", 1], [10.35, "Looking after yourself comes first.", 1], [12.81, "When you coach one person well, the whole team gains.", 2], [16.25, "Your Playbook asks you to name where that could happen.", 2], [19.27, "And the Starting Line sets the rhythm for everything after it.", 3], [22.83, "Book it this week.", 3], [24.15, "Select Download my answers for a Word copy of what you wrote in this lesson.", 4], [28.41, "If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", 4]], "v": "r3", "cues": [0.03, 3.35, 12.81, 19.27, 24.15]}, "pc_n_1_22": {"dur": 18.32, "text": "That's Lesson 1 done. Way to go, you've stepped into the Player-Coach role. This week, run your core rep: book and hold the Starting Line with your Athleader, then ask how it landed. Next time, you'll draft your own M.V.P.+V, because it's hard to coach someone through work you haven't done yourself.", "sents": [[0, "That's Lesson 1 done.", 0], [1.71, "Way to go, you've stepped into the Player-Coach role.", 0], [5.27, "This week, run your core rep: book and hold the Starting Line with your Athleader, then ask how it landed.", 1], [11.75, "Next time, you'll draft your own M.V.P.+V, because it's hard to coach someone through work you haven't done yourself.", 1]], "v": "r3", "cues": [0, 5.27]}, "pc_n_2_0": {"dur": 11.76, "text": "Lesson 2 is your scouting report, and it starts with you. You'll draft your own leadership blueprint, then learn how to respond when your Athleader shares something difficult. Select Start lesson.", "sents": [[0, "Lesson 2 is your scouting report, and it starts with you.", 0], [3.91, "You'll draft your own leadership blueprint, then learn how to respond when your Athleader shares something difficult.", 1], [10.17, "Select Start lesson.", 1]], "v": "r3", "cues": [0, 3.91]}, "pc_n_2_1": {"dur": 13.28, "text": "Read this moment, and picture yourself in it. That sentence is well meant, and it usually ends the conversation. This lesson gives you a different first sentence, and asks you to do your own scouting report before theirs.", "sents": [[0.05, "Read this moment, and picture yourself in it.", 0], [3.49, "That sentence is well meant, and it usually ends the conversation.", 1], [7.69, "This lesson gives you a different first sentence, and asks you to do your own scouting report before theirs.", 1]], "v": "r3", "cues": [0.05, 3.49]}, "pc_n_2_3": {"dur": 6.24, "text": "A quick look back at Lesson 1 before you start. Choose the answer you remember. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 1 before you start.", 0], [2.93, "Choose the answer you remember.", 1], [4.69, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 2.93]}, "pc_n_2_4": {"dur": 37.12, "text": "Here's what you'll practice in this lesson. You'll draft your own M.V.P.+V: your mission, vision, purpose and values. Your Athleader starts the same work this week with their values, and finishes it in Lesson 3. Yours goes first. When your Athleader shares something vulnerable, you'll have one sentence ready that thanks them, and one curious question that follows it. You'll learn a three-step way to give feedback that points forward: acknowledge the insight, connect it to what's next, and agree one action. And you'll use it in a real check-in this week. The Pulse Check picks this up at the end of the lesson.", "sents": [[0, "Here's what you'll practice in this lesson.", 0], [2.29, "You'll draft your own M.V.P.+V: your mission, vision, purpose and values.", 1], [8.53, "Your Athleader starts the same work this week with their values, and finishes it in Lesson 3.", 1], [13.83, "Yours goes first.", 1], [15.55, "When your Athleader shares something vulnerable, you'll have one sentence ready that thanks them, and one curious question that follows it.", 2], [22.93, "You'll learn a three-step way to give feedback that points forward: acknowledge the insight, connect it to what's next, and agree one action.", 3], [31.43, "And you'll use it in a real check-in this week.", 4], [34.35, "The Pulse Check picks this up at the end of the lesson.", 4]], "v": "r3", "cues": [0, 2.29, 15.55, 22.93, 31.43]}, "pc_n_2_7": {"dur": 10.8, "text": "Your M.V.P.+V has four parts, and you'll draft all of them in your Playbook this week. Select each one to hear what it asks of you. Open all four before you move on.", "sents": [[0.01, "Your M.V.P.+V has four parts, and you'll draft all of them in your Playbook this week.", 0], [5.85, "Select each one to hear what it asks of you.", 1], [8.63, "Open all four before you move on.", 1]], "v": "r3", "cues": [0.01, 5.85]}, "pc_n_2_7_purpose": {"dur": 8.8, "text": "Your purpose is your why. It's the lasting impact you want to have as a leader, and it should still be true if your title changed tomorrow.", "sents": [[0.01, "Your purpose is your why.", 0], [2.39, "It's the lasting impact you want to have as a leader, and it should still be true if your title changed tomorrow.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_2_7_vision": {"dur": 8.4, "text": "Your vision is where your leadership is heading, three to five years out. Picture the team you lead then, and what the people on it have become.", "sents": [[0.05, "Your vision is where your leadership is heading, three to five years out.", 0], [4.71, "Picture the team you lead then, and what the people on it have become.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_2_7_mission": {"dur": 10.08, "text": "Your mission is how you get there, day to day. Write it as one sentence: what you'll do, for whom, by focusing on what, to get which result.", "sents": [[0.01, "Your mission is how you get there, day to day.", 0], [3.35, "Write it as one sentence: what you'll do, for whom, by focusing on what, to get which result.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_2_7_values": {"dur": 12.88, "text": "Your values are the three to five foundations you come back to daily, and they shape your actions. Remember the executive in the video: her value was creativity, and a purely administrative role was draining her.", "sents": [[0.01, "Your values are the three to five foundations you come back to daily, and they shape your actions.", 0], [6.17, "Remember the executive in the video: her value was creativity, and a purely administrative role was draining her.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_2_9": {"dur": 29.84, "text": "Here's the example from the video, side by side. An employee shares a failure with their manager. It's a vulnerable moment. Manager A tells them what they should have done. It's advice, and it lands as judgment, so the conversation stops there. Manager B thanks them and asks what it taught them. The employee does the thinking, and they're likely to bring the next story too. Your first sentence decides whether you hear the second story. Your Playbook asks you to write yours down before the check-in.", "sents": [[0.03, "Here's the example from the video, side by side.", 0], [3.31, "An employee shares a failure with their manager.", 1], [6.33, "It's a vulnerable moment.", 1], [8.19, "Manager A tells them what they should have done.", 2], [10.81, "It's advice, and it lands as judgment, so the conversation stops there.", 2], [15.55, "Manager B thanks them and asks what it taught them.", 3], [18.87, "The employee does the thinking, and they're likely to bring the next story too.", 3], [22.83, "Your first sentence decides whether you hear the second story.", 4], [26.51, "Your Playbook asks you to write yours down before the check-in.", 4]], "v": "r3", "cues": [0.03, 3.31, 8.19, 15.55, 22.83]}, "pc_n_2_10": {"dur": 11.6, "text": "Try this one. For each coaching line, decide whether it looks back or looks forward. Forward-looking lines still take the past seriously. They just end on what the person will do next.", "sents": [[0.03, "Try this one.", 0], [1.27, "For each coaching line, decide whether it looks back or looks forward.", 0], [5.83, "Forward-looking lines still take the past seriously.", 1], [9.19, "They just end on what the person will do next.", 1]], "v": "r3", "cues": [0.03, 5.83]}, "pc_n_2_12": {"dur": 21.2, "text": "Here are the three steps from the video. First, acknowledge what they've noticed before you guide anything. It shows you heard them. Second, connect it to what's ahead. If they've found a strength, ask how they could use it on their ninety-day goal. Third, agree one small action with a date. That's what turns a good conversation into something they own.", "sents": [[0.01, "Here are the three steps from the video.", 0], [2.23, "First, acknowledge what they've noticed before you guide anything.", 1], [6.45, "It shows you heard them.", 1], [7.89, "Second, connect it to what's ahead.", 2], [10.51, "If they've found a strength, ask how they could use it on their ninety-day goal.", 2], [14.53, "Third, agree one small action with a date.", 3], [17.89, "That's what turns a good conversation into something they own.", 3]], "v": "r3", "cues": [0.01, 2.23, 7.89, 14.53]}, "pc_n_2_13": {"dur": 6.56, "text": "Now try the feedback steps on a real line from a check-in. Pick the response you'd give, and you'll hear where it leads.", "sents": [[0, "Now try the feedback steps on a real line from a check-in.", 0], [3.49, "Pick the response you'd give, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0, 3.49]}, "pc_n_2_13_o0": {"dur": 9.68, "text": "It's positive, and it moves on too fast. Nothing was acknowledged, and a development plan isn't an action with a date. Try the other option to compare.", "sents": [[0, "It's positive, and it moves on too fast.", 0], [3.37, "Nothing was acknowledged, and a development plan isn't an action with a date.", 0], [7.99, "Try the other option to compare.", 0]], "v": "r3", "cues": [0]}, "pc_n_2_13_o1": {"dur": 8.72, "text": "You acknowledged it, connected it to the month ahead and agreed one concrete action. That's the whole framework, and it took about ten seconds.", "sents": [[0.01, "You acknowledged it, connected it to the month ahead and agreed one concrete action.", 0], [5.29, "That's the whole framework, and it took about ten seconds.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_2_15": {"dur": 34.32, "text": "Your core rep this week happens inside a check-in you'd hold anyway: use the three feedback steps, and notice whether your habit is to analyze the past or build the next move. If you have more time, draft your own M.V.P.+V. Brainstorm ten to fifteen values and keep three to five, then draft your purpose, vision and mission. And write the sentence you'll say when your Athleader shares something vulnerable, and the question that follows it. Run your core rep, then ask your Athleader how it landed. Select Open your Lesson 2 pages to get started.", "sents": [[0.01, "Your core rep this week happens inside a check-in you'd hold anyway: use the three feedback steps, and notice whether your habit is to analyze the past or build the next move.", 0], [10.95, "If you have more time, draft your own M.V.P.+V.", 1], [14.83, "Brainstorm ten to fifteen values and keep three to five, then draft your purpose, vision and mission.", 1], [21.57, "And write the sentence you'll say when your Athleader shares something vulnerable, and the question that follows it.", 2], [27.11, "Run your core rep, then ask your Athleader how it landed.", 3], [30.95, "Select Open your Lesson 2 pages to get started.", 3]], "v": "r3", "cues": [0.01, 10.95, 21.57, 27.11]}, "pc_n_2_16": {"dur": 12.72, "text": "This lesson's Athleader Pro is LaChina Robinson, the Pressure Player. She works as a basketball analyst and broadcaster, and she knows what it takes to stay flexible when the pressure's on. Press play to hear from her.", "sents": [[0, "This lesson's Athleader Pro is LaChina Robinson, the Pressure Player.", 0], [4.89, "She works as a basketball analyst and broadcaster, and she knows what it takes to stay flexible when the pressure's on.", 1], [11.35, "Press play to hear from her.", 1]], "v": "r3", "cues": [0, 4.89]}, "pc_n_2_17": {"dur": 12.16, "text": "LaChina's drill helps you pivot under pressure, and it takes three minutes. Select Start the timer and work through each step. When you're done, or once you've planned when you'll run it, tick the box that fits.", "sents": [[0.05, "LaChina's drill helps you pivot under pressure, and it takes three minutes.", 0], [4.99, "Select Start the timer and work through each step.", 1], [7.99, "When you're done, or once you've planned when you'll run it, tick the box that fits.", 1]], "v": "r3", "cues": [0.05, 4.99]}, "pc_n_2_19_q0": {"dur": 8.16, "text": "A few questions on the main ideas. First: why do you draft your own M.V.P.+V before coaching your Athleader through theirs?", "sents": [[0, "A few questions on the main ideas.", 0], [2.21, "First: why do you draft your own M.V.P.+V before coaching your Athleader through theirs?", 0]], "v": "r3", "cues": [0]}, "pc_n_2_19_w0": {"dur": 7.2, "text": "Doing it yourself shows you where it's hard and where it's vulnerable, which makes you a better coach when your Athleader shares theirs.", "sents": [[0, "Doing it yourself shows you where it's hard and where it's vulnerable, which makes you a better coach when your Athleader shares theirs.", 0]], "v": "r3", "cues": [0]}, "pc_n_2_19_q1": {"dur": 5.6, "text": "Your Athleader tells you about a setback. Which first response builds psychological safety?", "sents": [[0, "Your Athleader tells you about a setback.", 0], [2.69, "Which first response builds psychological safety?", 0]], "v": "r3", "cues": [0]}, "pc_n_2_19_w1": {"dur": 9.12, "text": "It thanks them for trusting you and hands the meaning back to them, without judging. Reassurance sounds kind, and it closes the topic just as fast.", "sents": [[0, "It thanks them for trusting you and hands the meaning back to them, without judging.", 0], [4.99, "Reassurance sounds kind, and it closes the topic just as fast.", 0]], "v": "r3", "cues": [0]}, "pc_n_2_19_q2": {"dur": 2.88, "text": "What is the second step of forward-looking feedback?", "sents": [[0, "What is the second step of forward-looking feedback?", 0]], "v": "r3", "cues": [0]}, "pc_n_2_19_w2": {"dur": 6.48, "text": "Acknowledge first, then connect the insight to what's ahead, then agree one action with a date.", "sents": [[0, "Acknowledge first, then connect the insight to what's ahead, then agree one action with a date.", 0]], "v": "r3", "cues": [0]}, "pc_n_2_19_q3": {"dur": 6.4, "text": "Last one. Your Athleader only ever shares good news in check-ins. What's the best move?", "sents": [[0.15, "Last one.", 0], [1.27, "Your Athleader only ever shares good news in check-ins.", 0], [5.21, "What's the best move?", 0]], "v": "r3", "cues": [0.15]}, "pc_n_2_19_w3": {"dur": 8.24, "text": "Sharing something real first shows that setbacks are safe to talk about. Then an open question gives them room to do the same.", "sents": [[0.05, "Sharing something real first shows that setbacks are safe to talk about.", 0], [4.93, "Then an open question gives them room to do the same.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_2_20": {"dur": 35.44, "text": "Before you go, here's what to keep from this lesson. Your scouting report comes first. Draft your M.V.P.+V in your own words, however rough, before your Athleader shares theirs. When someone shares something hard, your first sentence decides whether they keep talking. Thank them, then ask. And feedback points forward: acknowledge, connect to what's next, agree one action with a date. Select Download my answers for a Word copy of what you wrote today. If you'd like to go further, Chapter 8 of the book is about reading a setback the way a coach reads film.", "sents": [[0.03, "Before you go, here's what to keep from this lesson.", 0], [3.35, "Your scouting report comes first.", 1], [5.85, "Draft your M.V.P.+V in your own words, however rough, before your Athleader shares theirs.", 1], [12.27, "When someone shares something hard, your first sentence decides whether they keep talking.", 2], [17.11, "Thank them, then ask.", 2], [19.17, "And feedback points forward: acknowledge, connect to what's next, agree one action with a date.", 3], [25.75, "Select Download my answers for a Word copy of what you wrote today.", 4], [29.71, "If you'd like to go further, Chapter 8 of the book is about reading a setback the way a coach reads film.", 4]], "v": "r3", "cues": [0.03, 3.35, 12.27, 19.17, 25.75]}, "pc_n_2_21": {"dur": 17.36, "text": "That's Lesson 2 done. Keep going, your coaching is already changing. This week, run your core rep: use the three feedback steps in your next check-in, and ask how it landed. Next time, you'll set one ninety-day goal for your own leadership, then help your team choose theirs.", "sents": [[0.03, "That's Lesson 2 done.", 0], [1.99, "Keep going, your coaching is already changing.", 0], [5.53, "This week, run your core rep: use the three feedback steps in your next check-in, and ask how it landed.", 1], [11.77, "Next time, you'll set one ninety-day goal for your own leadership, then help your team choose theirs.", 1]], "v": "r3", "cues": [0.03, 5.53]}, "pc_n_3_0": {"dur": 12.8, "text": "Lesson 3 is the game plan: yours first, then your team's. You'll set one ninety-day goal for your own leadership, then learn how to bring your team to one shared goal. Select Start lesson.", "sents": [[0.01, "Lesson 3 is the game plan: yours first, then your team's.", 0], [4.67, "You'll set one ninety-day goal for your own leadership, then learn how to bring your team to one shared goal.", 1], [11.31, "Select Start lesson.", 1]], "v": "r3", "cues": [0.01, 4.67]}, "pc_n_3_1": {"dur": 15.6, "text": "Read this moment, and picture your own team in it. Ten priorities usually means none. This lesson gives you one question that brings a team down to one, and asks you to set your own goal first, so you're modeling the focus you want from them.", "sents": [[0, "Read this moment, and picture your own team in it.", 0], [3.77, "Ten priorities usually means none.", 1], [6.63, "This lesson gives you one question that brings a team down to one, and asks you to set your own goal first, so you're modeling the focus you want from them.", 1]], "v": "r3", "cues": [0, 3.77]}, "pc_n_3_3": {"dur": 6.16, "text": "A quick look back at Lesson 2 before you start. Choose the answer you remember. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 2 before you start.", 0], [2.91, "Choose the answer you remember.", 1], [4.69, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 2.91]}, "pc_n_3_4": {"dur": 32.4, "text": "Here's what you'll practice in this lesson. You'll write one ninety-day goal about how you lead. Something specific and measurable, with a start date, and about your leadership rather than a project. You'll name the one habit or meeting most likely to derail it, and which of the Core 4 it will test. You'll learn the question that brings a team from ten priorities to one, and how to keep it in front of them every week. And when the first roadblock arrives, you'll have a way to coach the team through it instead of clearing it yourself. The Pulse Check picks this up at the end of the lesson.", "sents": [[0.01, "Here's what you'll practice in this lesson.", 0], [2.25, "You'll write one ninety-day goal about how you lead.", 1], [5.51, "Something specific and measurable, with a start date, and about your leadership rather than a project.", 1], [11.39, "You'll name the one habit or meeting most likely to derail it, and which of the Core 4 it will test.", 2], [17.43, "You'll learn the question that brings a team from ten priorities to one, and how to keep it in front of them every week.", 3], [23.81, "And when the first roadblock arrives, you'll have a way to coach the team through it instead of clearing it yourself.", 4], [29.13, "The Pulse Check picks this up at the end of the lesson.", 4]], "v": "r3", "cues": [0.01, 2.25, 11.39, 17.43, 23.81]}, "pc_n_3_7": {"dur": 26.0, "text": "The 90-Day Way works at two levels, and yours comes first. Your own goal is about how you lead. Melissa's example is a manager who delegated one significant responsibility to free five hours a week for strategic thinking. It's specific and measurable, and it changes how she works. Then you bring the same system to your team. One question gets them to one shared goal, and every weekly check-in opens with it.", "sents": [[0.03, "The 90-Day Way works at two levels, and yours comes first.", 0], [4.53, "Your own goal is about how you lead.", 1], [7.35, "Melissa's example is a manager who delegated one significant responsibility to free five hours a week for strategic thinking.", 1], [14.83, "It's specific and measurable, and it changes how she works.", 1], [18.69, "Then you bring the same system to your team.", 2], [21.39, "One question gets them to one shared goal, and every weekly check-in opens with it.", 2]], "v": "r3", "cues": [0.03, 4.53, 18.69]}, "pc_n_3_8": {"dur": 13.6, "text": "Try this before you write your own. For each goal, decide whether it's about your leadership or about a project. The test is simple. A leadership goal changes something about how you lead, and you could start it next week.", "sents": [[0.03, "Try this before you write your own.", 0], [2.25, "For each goal, decide whether it's about your leadership or about a project.", 0], [7.09, "The test is simple.", 1], [8.63, "A leadership goal changes something about how you lead, and you could start it next week.", 1]], "v": "r3", "cues": [0.03, 7.09]}, "pc_n_3_10": {"dur": 30.64, "text": "Here's the shape of the story from the video. A team had ten priorities, all urgent, and nothing was getting finished. Their manager brought them together and asked one question: what is the one thing we must achieve this quarter to be successful? They chose one initiative. Every weekly check-in started with it, and the team became more focused and worked together better. The question only works if you keep asking it. Your Playbook this week asks you to write your version and hold that team conversation.", "sents": [[0.03, "Here's the shape of the story from the video.", 0], [2.65, "A team had ten priorities, all urgent, and nothing was getting finished.", 1], [8.07, "Their manager brought them together and asked one question: what is the one thing we must achieve this quarter to be successful?", 2], [15.53, "They chose one initiative.", 3], [17.41, "Every weekly check-in started with it, and the team became more focused and worked together better.", 3], [22.97, "The question only works if you keep asking it.", 4], [26.03, "Your Playbook this week asks you to write your version and hold that team conversation.", 4]], "v": "r3", "cues": [0.03, 2.65, 8.07, 15.53, 22.97]}, "pc_n_3_12": {"dur": 27.36, "text": "Here's the sequence from the budget-cut story, step by step. First, name the new reality out loud. It tells the team you're not pretending the problem away. Then ask what's still possible. The goal stays alive, with the constraint attached. Ask what the constraint forces you to consider. That's where the creative options come from. Then stop talking. The team's answer is the one they'll own, and next time they'll start there without you.", "sents": [[0.01, "Here's the sequence from the budget-cut story, step by step.", 0], [3.79, "First, name the new reality out loud.", 1], [7.05, "It tells the team you're not pretending the problem away.", 1], [10.25, "Then ask what's still possible.", 2], [12.67, "The goal stays alive, with the constraint attached.", 2], [15.91, "Ask what the constraint forces you to consider.", 3], [18.63, "That's where the creative options come from.", 3], [20.85, "Then stop talking.", 4], [22.65, "The team's answer is the one they'll own, and next time they'll start there without you.", 4]], "v": "r3", "cues": [0.01, 3.79, 10.25, 15.91, 20.85]}, "pc_n_3_13": {"dur": 9.44, "text": "Let's test it in the moment it's hardest. Your team's plan just lost its budget, and they're looking at you. Pick your first sentence, and you'll hear where it leads.", "sents": [[0, "Let's test it in the moment it's hardest.", 0], [2.89, "Your team's plan just lost its budget, and they're looking at you.", 1], [6.75, "Pick your first sentence, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0, 2.89]}, "pc_n_3_13_o0": {"dur": 11.2, "text": "It's quick and it sounds decisive. It also takes the problem away from the people who need to learn to solve it, so at the next roadblock they'll wait for you again. Try the other option to compare.", "sents": [[0, "It's quick and it sounds decisive.", 0], [2.91, "It also takes the problem away from the people who need to learn to solve it, so at the next roadblock they'll wait for you again.", 0], [9.55, "Try the other option to compare.", 0]], "v": "r3", "cues": [0]}, "pc_n_3_13_o1": {"dur": 8.64, "text": "You named the reality, kept the goal alive and handed the thinking back to the team with the constraint attached. That's coaching through a roadblock.", "sents": [[0.01, "You named the reality, kept the goal alive and handed the thinking back to the team with the constraint attached.", 0], [6.71, "That's coaching through a roadblock.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_3_15": {"dur": 29.6, "text": "Your core rep this week is your own game plan, about twenty minutes: one leadership goal, one measure, one date and a first step this week. Add it to your Scorecard as well. If you have more time, write your version of the one-goal question, hold the team conversation, and capture the shared goal and how often you'll check it. And write the two questions you'll ask when the first roadblock hits. Run your core rep, then ask one person how it landed. Select Open your Lesson 3 pages to get started.", "sents": [[0.01, "Your core rep this week is your own game plan, about twenty minutes: one leadership goal, one measure, one date and a first step this week.", 0], [9.23, "Add it to your Scorecard as well.", 0], [11.17, "If you have more time, write your version of the one-goal question, hold the team conversation, and capture the shared goal and how often you'll check it.", 1], [19.35, "And write the two questions you'll ask when the first roadblock hits.", 2], [22.91, "Run your core rep, then ask one person how it landed.", 3], [26.35, "Select Open your Lesson 3 pages to get started.", 3]], "v": "r3", "cues": [0.01, 11.17, 19.35, 22.91]}, "pc_n_3_16": {"dur": 12.96, "text": "This lesson's Athleader Pro is Stephanie Johnson, the Momentum Maker. She leads her own company and talks about turning adversity into momentum, for a team and for yourself. Press play to hear from her.", "sents": [[0, "This lesson's Athleader Pro is Stephanie Johnson, the Momentum Maker.", 0], [4.85, "She leads her own company and talks about turning adversity into momentum, for a team and for yourself.", 1], [11.57, "Press play to hear from her.", 1]], "v": "r3", "cues": [0, 4.85]}, "pc_n_3_17": {"dur": 12.32, "text": "Stephanie's drill helps you realign under pressure, and it takes three minutes. Select Start the timer and work through each step. When you're done, or once you've planned when you'll run it, tick the box that fits.", "sents": [[0.05, "Stephanie's drill helps you realign under pressure, and it takes three minutes.", 0], [5.01, "Select Start the timer and work through each step.", 1], [8.09, "When you're done, or once you've planned when you'll run it, tick the box that fits.", 1]], "v": "r3", "cues": [0.05, 5.01]}, "pc_n_3_19_q0": {"dur": 7.6, "text": "A few questions on the main ideas. First: which of these is a ninety-day leadership goal rather than a project goal?", "sents": [[0, "A few questions on the main ideas.", 0], [2.31, "First: which of these is a ninety-day leadership goal rather than a project goal?", 0]], "v": "r3", "cues": [0]}, "pc_n_3_19_w0": {"dur": 8.16, "text": "It changes how you spend your time as a leader, and it has a clear start date. The others are outputs the team delivers.", "sents": [[0, "It changes how you spend your time as a leader, and it has a clear start date.", 0], [5.51, "The others are outputs the team delivers.", 0]], "v": "r3", "cues": [0]}, "pc_n_3_19_q1": {"dur": 4.16, "text": "Why do you set your own ninety-day goal before your team sets theirs?", "sents": [[0.05, "Why do you set your own ninety-day goal before your team sets theirs?", 0]], "v": "r3", "cues": [0.05]}, "pc_n_3_19_w1": {"dur": 9.2, "text": "A team takes focus from what its leader does. Having your own plan also shows you where the roadblocks are before you ask anyone else to face them.", "sents": [[0.07, "A team takes focus from what its leader does.", 0], [3.29, "Having your own plan also shows you where the roadblocks are before you ask anyone else to face them.", 0]], "v": "r3", "cues": [0.07]}, "pc_n_3_19_q2": {"dur": 6.48, "text": "A team member says the 90-Day Way is just another corporate initiative. What's the best first response?", "sents": [[0, "A team member says the 90-Day Way is just another corporate initiative.", 0], [4.55, "What's the best first response?", 0]], "v": "r3", "cues": [0]}, "pc_n_3_19_w2": {"dur": 10.56, "text": "Skepticism usually means they've seen initiatives fade before. Asking what would make it worth their time brings them into shaping the goal, which is where buy-in comes from.", "sents": [[0.05, "Skepticism usually means they've seen initiatives fade before.", 0], [4.55, "Asking what would make it worth their time brings them into shaping the goal, which is where buy-in comes from.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_3_19_q3": {"dur": 5.28, "text": "Last one. The first roadblock hits. What is your role as a Player-Coach?", "sents": [[0.01, "Last one.", 0], [1.09, "The first roadblock hits.", 0], [3.21, "What is your role as a Player-Coach?", 0]], "v": "r3", "cues": [0.01]}, "pc_n_3_19_w3": {"dur": 9.92, "text": "If you clear every roadblock, the team learns to wait for you. Naming the reality and asking what's still possible builds their ability to solve the next one.", "sents": [[0, "If you clear every roadblock, the team learns to wait for you.", 0], [4.33, "Naming the reality and asking what's still possible builds their ability to solve the next one.", 0]], "v": "r3", "cues": [0]}, "pc_n_3_20": {"dur": 31.68, "text": "Before you go, here's what to keep from this lesson. Your own ninety-day goal comes first. You're modeling the focus you want to see. One question brings a team from ten priorities to one: what is the one thing we must achieve this quarter? Then you ask it again every week. And when the roadblock comes, name the reality, ask what's still possible, and let the team find the way. Select Download my answers for a Word copy of what you wrote today. Chapter 11 of the book is all about the 90-Day Way.", "sents": [[0.03, "Before you go, here's what to keep from this lesson.", 0], [3.35, "Your own ninety-day goal comes first.", 1], [6.23, "You're modeling the focus you want to see.", 1], [8.93, "One question brings a team from ten priorities to one: what is the one thing we must achieve this quarter?", 2], [15.65, "Then you ask it again every week.", 2], [18.19, "And when the roadblock comes, name the reality, ask what's still possible, and let the team find the way.", 3], [24.61, "Select Download my answers for a Word copy of what you wrote today.", 4], [28.47, "Chapter 11 of the book is all about the 90-Day Way.", 4]], "v": "r3", "cues": [0.03, 3.35, 8.93, 18.19, 24.61]}, "pc_n_3_21": {"dur": 15.2, "text": "That's Lesson 3 done. Halfway through your season, and your team can see it. This week, run your core rep, your ninety-day leadership goal, and ask one person how it landed. Next time, pressure, and what your team learns from how you handle it.", "sents": [[0, "That's Lesson 3 done.", 0], [1.99, "Halfway through your season, and your team can see it.", 0], [5.41, "This week, run your core rep, your ninety-day leadership goal, and ask one person how it landed.", 1], [11.21, "Next time, pressure, and what your team learns from how you handle it.", 1]], "v": "r3", "cues": [0, 5.41]}, "pc_n_4_0": {"dur": 12.08, "text": "Lesson 4 is about the moment your plan meets pressure. You'll build your own first move for when things go wrong, then learn to coach your team through resistance and change. Select Start lesson.", "sents": [[0.03, "Lesson 4 is about the moment your plan meets pressure.", 0], [4.01, "You'll build your own first move for when things go wrong, then learn to coach your team through resistance and change.", 1], [10.55, "Select Start lesson.", 1]], "v": "r3", "cues": [0.03, 4.01]}, "pc_n_4_1": {"dur": 13.68, "text": "Read this moment, and notice your own first instinct. What you do in the next ten minutes sets your team's stress level for the month. This lesson gives you a first move for yourself, and two coaching questions for what comes after.", "sents": [[0, "Read this moment, and notice your own first instinct.", 0], [4.03, "What you do in the next ten minutes sets your team's stress level for the month.", 1], [8.51, "This lesson gives you a first move for yourself, and two coaching questions for what comes after.", 1]], "v": "r3", "cues": [0, 4.03]}, "pc_n_4_3": {"dur": 6.4, "text": "A quick look back at Lesson 3 before you start. Choose the answer you remember. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 3 before you start.", 0], [2.95, "Choose the answer you remember.", 1], [4.85, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 2.95]}, "pc_n_4_4": {"dur": 31.52, "text": "Here's what you'll practice in this lesson. You'll define your own first move under pressure: one short, repeatable action that separates the emotion from the data before you decide anything. When people resist a change, you'll learn to ask what they're afraid of losing. Melissa names three things: certainty, competence and connection. You'll add one agility question to your coaching, and ask it before you offer a solution. And you'll use it in a real conversation this week. The Pulse Check picks this up at the end of the lesson.", "sents": [[0.01, "Here's what you'll practice in this lesson.", 0], [2.25, "You'll define your own first move under pressure: one short, repeatable action that separates the emotion from the data before you decide anything.", 1], [11.67, "When people resist a change, you'll learn to ask what they're afraid of losing.", 2], [16.19, "Melissa names three things: certainty, competence and connection.", 2], [20.81, "You'll add one agility question to your coaching, and ask it before you offer a solution.", 3], [25.77, "And you'll use it in a real conversation this week.", 4], [28.45, "The Pulse Check picks this up at the end of the lesson.", 4]], "v": "r3", "cues": [0.01, 2.25, 11.67, 20.81, 25.77]}, "pc_n_4_7": {"dur": 34.72, "text": "Here's how the CEO's ten-minute walk works as a play you can repeat. First, notice what you reach for when the bad news lands. For many managers it's a meeting or a fast email. Then put ten minutes between the news and your response. A walk, a page of notes or a closed door, whatever lets you separate the emotion from the data. Decide what to do after that. If you still need the meeting, open it with a question rather than a plan. And repeat it every time, until it's your default. Drill 4.2 in your Playbook is where you write yours down.", "sents": [[0.03, "Here's how the CEO's ten-minute walk works as a play you can repeat.", 0], [4.39, "First, notice what you reach for when the bad news lands.", 1], [8.25, "For many managers it's a meeting or a fast email.", 1], [11.81, "Then put ten minutes between the news and your response.", 2], [15.69, "A walk, a page of notes or a closed door, whatever lets you separate the emotion from the data.", 2], [21.99, "Decide what to do after that.", 3], [23.99, "If you still need the meeting, open it with a question rather than a plan.", 3], [28.09, "And repeat it every time, until it's your default.", 4], [31.55, "Drill 4.2 in your Playbook is where you write yours down.", 4]], "v": "r3", "cues": [0.03, 4.39, 11.81, 21.99, 28.09]}, "pc_n_4_9": {"dur": 12.64, "text": "Resistance to change is rarely about the change itself. It's usually about what people fear they'll lose. Select each one to hear how it sounds and what to ask. Open all three before you move on.", "sents": [[0.03, "Resistance to change is rarely about the change itself.", 0], [3.95, "It's usually about what people fear they'll lose.", 0], [7.05, "Select each one to hear how it sounds and what to ask.", 1], [10.57, "Open all three before you move on.", 1]], "v": "r3", "cues": [0.03, 7.05]}, "pc_n_4_9_certainty": {"dur": 11.44, "text": "Certainty is about not knowing. You'll hear it as questions about timing, roles and what happens next. Ask what the biggest unknown is for them, and answer what you can.", "sents": [[0.09, "Certainty is about not knowing.", 0], [2.83, "You'll hear it as questions about timing, roles and what happens next.", 0], [7.41, "Ask what the biggest unknown is for them, and answer what you can.", 0]], "v": "r3", "cues": [0.09]}, "pc_n_4_9_competence": {"dur": 11.52, "text": "Competence is the fear of looking slow or getting it wrong. That was the software team in the video. Ask what they'd need to feel ready, whether that's training time or permission to be slow for a while.", "sents": [[0.07, "Competence is the fear of looking slow or getting it wrong.", 0], [4.13, "That was the software team in the video.", 0], [6.21, "Ask what they'd need to feel ready, whether that's training time or permission to be slow for a while.", 0]], "v": "r3", "cues": [0.07]}, "pc_n_4_9_connection": {"dur": 10.72, "text": "Connection is about people. A change can split a team or move someone away from colleagues they rely on. Ask what they're most worried about losing, and look for a way to keep it.", "sents": [[0.03, "Connection is about people.", 0], [2.23, "A change can split a team or move someone away from colleagues they rely on.", 0], [6.85, "Ask what they're most worried about losing, and look for a way to keep it.", 0]], "v": "r3", "cues": [0.03]}, "pc_n_4_10": {"dur": 27.6, "text": "Here's the example from the video. A manager rolled out new software, and her team was slow to use it. Instead of pushing harder, she held one-on-ones and asked what worried them most about the new system. It turned out they were afraid they wouldn't learn it fast enough and would look incompetent. That was the fear to address. Diagnose first. Your Playbook asks you to pick one change on your team and name which loss is behind the resistance.", "sents": [[0.01, "Here's the example from the video.", 0], [2.17, "A manager rolled out new software, and her team was slow to use it.", 1], [6.83, "Instead of pushing harder, she held one-on-ones and asked what worried them most about the new system.", 2], [12.97, "It turned out they were afraid they wouldn't learn it fast enough and would look incompetent.", 3], [17.89, "That was the fear to address.", 3], [20.15, "Diagnose first.", 4], [21.87, "Your Playbook asks you to pick one change on your team and name which loss is behind the resistance.", 4]], "v": "r3", "cues": [0.01, 2.17, 6.83, 12.97, 20.15]}, "pc_n_4_12": {"dur": 9.68, "text": "Now try the agility question in a tense moment. Your Athleader is upset, and a quick fix is tempting. Pick your first sentence, and you'll hear where it leads.", "sents": [[0.05, "Now try the agility question in a tense moment.", 0], [3.33, "Your Athleader is upset, and a quick fix is tempting.", 1], [6.95, "Pick your first sentence, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0.05, 3.33]}, "pc_n_4_12_o0": {"dur": 9.36, "text": "You've solved it, and quickly. You've also taught them that panicking gets you to solve it, so next time they'll come to you sooner. Try the other option to compare.", "sents": [[0.01, "You've solved it, and quickly.", 0], [2.35, "You've also taught them that panicking gets you to solve it, so next time they'll come to you sooner.", 0], [7.71, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_4_12_o1": {"dur": 10.16, "text": "One question moves them from panic to problem-solving, and the answer they find is theirs. That's the shift from chief problem solver to chief question asker.", "sents": [[0, "One question moves them from panic to problem-solving, and the answer they find is theirs.", 0], [6.07, "That's the shift from chief problem solver to chief question asker.", 0]], "v": "r3", "cues": [0]}, "pc_n_4_14": {"dur": 30.08, "text": "Your core rep this week happens inside real work: use the agility question in one real conversation, and note what changed when you asked instead of solved. If you have more time, write your own first move: what triggers it, what you'll do for ten minutes, and where. And pick one resistance on your team, name which loss is behind it, and write the question you'll ask in a one-on-one. Run your core rep, then ask one person how it landed. Select Open your Lesson 4 pages to get started.", "sents": [[0.01, "Your core rep this week happens inside real work: use the agility question in one real conversation, and note what changed when you asked instead of solved.", 0], [10.69, "If you have more time, write your own first move: what triggers it, what you'll do for ten minutes, and where.", 1], [17.19, "And pick one resistance on your team, name which loss is behind it, and write the question you'll ask in a one-on-one.", 2], [23.83, "Run your core rep, then ask one person how it landed.", 3], [26.69, "Select Open your Lesson 4 pages to get started.", 3]], "v": "r3", "cues": [0.01, 10.69, 17.19, 23.83]}, "pc_n_4_15": {"dur": 12.56, "text": "This lesson's Athleader Pro is Dr. Michael Mannino, the Flow Alchemist. His work sits where neuroscience meets peak performance, and his drill is one you run with your team. Press play to hear from him.", "sents": [[0, "This lesson's Athleader Pro is Dr. Michael Mannino, the Flow Alchemist.", 0], [5.01, "His work sits where neuroscience meets peak performance, and his drill is one you run with your team.", 1], [11.19, "Press play to hear from him.", 1]], "v": "r3", "cues": [0, 5.01]}, "pc_n_4_16": {"dur": 13.68, "text": "Michael's drill builds team resilience, and you run it with your team. It takes about three minutes. Select Start the timer and take the team through each step. When you've run it, or once you've planned when you will, tick the box that fits.", "sents": [[0, "Michael's drill builds team resilience, and you run it with your team.", 0], [4.27, "It takes about three minutes.", 0], [5.91, "Select Start the timer and take the team through each step.", 1], [9.39, "When you've run it, or once you've planned when you will, tick the box that fits.", 1]], "v": "r3", "cues": [0, 5.91]}, "pc_n_4_18_q0": {"dur": 8.96, "text": "A few questions on the main ideas. First: a team member keeps forgetting to use the new process. What does diagnosing the resistance mean?", "sents": [[0, "A few questions on the main ideas.", 0], [2.19, "First: a team member keeps forgetting to use the new process.", 0], [6.59, "What does diagnosing the resistance mean?", 0]], "v": "r3", "cues": [0]}, "pc_n_4_18_w0": {"dur": 10.16, "text": "Resistance is usually about a loss: certainty, competence or connection. Once you know which one, you can address it directly instead of pushing harder.", "sents": [[0.05, "Resistance is usually about a loss: certainty, competence or connection.", 0], [5.77, "Once you know which one, you can address it directly instead of pushing harder.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_4_18_q1": {"dur": 3.04, "text": "What is the purpose of your ten-minute first move?", "sents": [[0.07, "What is the purpose of your ten-minute first move?", 0]], "v": "r3", "cues": [0.07]}, "pc_n_4_18_w1": {"dur": 9.36, "text": "Your team takes its cue from you. A short, repeatable pause lets you decide from clarity, so you bring a question to the meeting rather than your stress.", "sents": [[0.01, "Your team takes its cue from you.", 0], [2.55, "A short, repeatable pause lets you decide from clarity, so you bring a question to the meeting rather than your stress.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_4_18_q2": {"dur": 7.52, "text": "Your Athleader's ninety-day goal is at risk after a reorganization, and they want to give up. What's your best first move?", "sents": [[0.01, "Your Athleader's ninety-day goal is at risk after a reorganization, and they want to give up.", 0], [5.83, "What's your best first move?", 0]], "v": "r3", "cues": [0.01]}, "pc_n_4_18_w2": {"dur": 6.8, "text": "The agility question moves them from frustration to options, and whatever they come up with is theirs to own.", "sents": [[0.05, "The agility question moves them from frustration to options, and whatever they come up with is theirs to own.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_4_18_q3": {"dur": 7.36, "text": "Last one. Which fear is most likely behind this line: I don't know what this change means for my role?", "sents": [[0.03, "Last one.", 0], [1.19, "Which fear is most likely behind this line: I don't know what this change means for my role?", 0]], "v": "r3", "cues": [0.03]}, "pc_n_4_18_w3": {"dur": 7.52, "text": "Not knowing what happens next is a loss of certainty. Ask what their biggest unknown is, and answer what you can.", "sents": [[0, "Not knowing what happens next is a loss of certainty.", 0], [3.77, "Ask what their biggest unknown is, and answer what you can.", 0]], "v": "r3", "cues": [0]}, "pc_n_4_19": {"dur": 31.52, "text": "Before you go, here's what to keep from this lesson. Put ten minutes between the pressure and your response. Separate the emotion from the data, then decide. When people resist, find out what they're afraid of losing: certainty, competence or connection. Address that first. And when your Athleader brings you a problem, ask what the constraint makes possible before you offer an answer. Select Download my answers for a Word copy of what you wrote today. Chapter 7 of the book goes further on agility.", "sents": [[0.01, "Before you go, here's what to keep from this lesson.", 0], [3.39, "Put ten minutes between the pressure and your response.", 1], [6.83, "Separate the emotion from the data, then decide.", 1], [10.63, "When people resist, find out what they're afraid of losing: certainty, competence or connection.", 2], [16.81, "Address that first.", 2], [18.55, "And when your Athleader brings you a problem, ask what the constraint makes possible before you offer an answer.", 3], [24.79, "Select Download my answers for a Word copy of what you wrote today.", 4], [28.25, "Chapter 7 of the book goes further on agility.", 4]], "v": "r3", "cues": [0.01, 3.39, 10.63, 18.55, 24.79]}, "pc_n_4_20": {"dur": 16.4, "text": "That's Lesson 4 done. Four down, and you're asking more than you're fixing. This week, run your core rep: use the agility question in one real conversation, and ask how it landed. Next time, the long game: your energy, and how your team recovers.", "sents": [[0.05, "That's Lesson 4 done.", 0], [1.83, "Four down, and you're asking more than you're fixing.", 0], [5.15, "This week, run your core rep: use the agility question in one real conversation, and ask how it landed.", 1], [11.91, "Next time, the long game: your energy, and how your team recovers.", 1]], "v": "r3", "cues": [0.05, 5.15]}, "pc_n_5_0": {"dur": 11.76, "text": "Lesson 5 is about lasting the whole season. You'll look at your own energy first, then at what your team copies from you, and how you lead them through recovery. Select Start lesson.", "sents": [[0.01, "Lesson 5 is about lasting the whole season.", 0], [3.63, "You'll look at your own energy first, then at what your team copies from you, and how you lead them through recovery.", 1], [10.37, "Select Start lesson.", 1]], "v": "r3", "cues": [0.01, 3.63]}, "pc_n_5_1": {"dur": 13.92, "text": "Read this moment. Which message do you think your team heard? Teams copy what their leader does far more than what the leader says. This lesson starts with your own energy, then one practice your team will see you keep.", "sents": [[0, "Read this moment.", 0], [1.79, "Which message do you think your team heard?", 0], [4.31, "Teams copy what their leader does far more than what the leader says.", 1], [8.65, "This lesson starts with your own energy, then one practice your team will see you keep.", 1]], "v": "r3", "cues": [0, 4.31]}, "pc_n_5_3": {"dur": 6.16, "text": "A quick look back at Lesson 4 before you start. Choose the answer you remember. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 4 before you start.", 0], [2.93, "Choose the answer you remember.", 1], [4.61, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 2.93]}, "pc_n_5_4": {"dur": 26.24, "text": "Here's what you'll practice in this lesson. You'll track your energy for a day and note what drains you and what fuels you. From that, you'll protect one block on next week's calendar, for deep work or for recovery. You'll choose one sustainable practice your team will see you do, and say out loud why you do it. And after the next hard stretch, you'll lead a recovery session before anyone plans the next push. The Pulse Check picks this up at the end of the lesson.", "sents": [[0.01, "Here's what you'll practice in this lesson.", 0], [2.27, "You'll track your energy for a day and note what drains you and what fuels you.", 1], [6.89, "From that, you'll protect one block on next week's calendar, for deep work or for recovery.", 2], [12.45, "You'll choose one sustainable practice your team will see you do, and say out loud why you do it.", 3], [17.99, "And after the next hard stretch, you'll lead a recovery session before anyone plans the next push.", 4], [23.59, "The Pulse Check picks this up at the end of the lesson.", 4]], "v": "r3", "cues": [0.01, 2.27, 6.89, 12.45, 17.99]}, "pc_n_5_7": {"dur": 26.48, "text": "Here's the difference Melissa describes in the video. Managing time means filling every slot. Meetings run back to back, replies go out at all hours, and a lot of the day is spent at low energy. Managing energy means protecting your best hours. The executive in the video blocks ninety minutes of deep work first thing and takes two short recovery breaks in the afternoon, and she gets more done in six hours than most people do in ten.", "sents": [[0, "Here's the difference Melissa describes in the video.", 0], [2.95, "Managing time means filling every slot.", 1], [6.09, "Meetings run back to back, replies go out at all hours, and a lot of the day is spent at low energy.", 1], [12.41, "Managing energy means protecting your best hours.", 2], [15.89, "The executive in the video blocks ninety minutes of deep work first thing and takes two short recovery breaks in the afternoon, and she gets more done in six hours than most people do in ten.", 2]], "v": "r3", "cues": [0, 2.95, 12.41]}, "pc_n_5_9": {"dur": 29.36, "text": "Here's the story from the video. A manager noticed his team sending emails at all hours, and people were getting worn down. In the next team meeting he said he didn't expect replies outside work hours, and asked everyone to use schedule-send for anything written after six. Then he did it himself. The team's habits changed, because he named the practice and they could see him keep it. Your Playbook asks you to choose one practice like this for the week, and the sentence you'll use to name it.", "sents": [[0.05, "Here's the story from the video.", 0], [2.13, "A manager noticed his team sending emails at all hours, and people were getting worn down.", 1], [8.29, "In the next team meeting he said he didn't expect replies outside work hours, and asked everyone to use schedule-send for anything written after six.", 2], [16.95, "Then he did it himself.", 2], [18.79, "The team's habits changed, because he named the practice and they could see him keep it.", 3], [23.77, "Your Playbook asks you to choose one practice like this for the week, and the sentence you'll use to name it.", 4]], "v": "r3", "cues": [0.05, 2.13, 8.29, 18.79, 23.77]}, "pc_n_5_11": {"dur": 24.0, "text": "Here's the recovery session from the video, in order. Start by celebrating the wins, specifically and by name. Then capture the lessons: what worked, and what you'd change next time. Give something back. The manager in the video gave everyone an extra half-day. Only then do you plan the next push. The order matters, because it shows the team that recovery is real.", "sents": [[0.03, "Here's the recovery session from the video, in order.", 0], [3.19, "Start by celebrating the wins, specifically and by name.", 1], [7.83, "Then capture the lessons: what worked, and what you'd change next time.", 2], [12.39, "Give something back.", 3], [13.95, "The manager in the video gave everyone an extra half-day.", 3], [17.47, "Only then do you plan the next push.", 4], [20.03, "The order matters, because it shows the team that recovery is real.", 4]], "v": "r3", "cues": [0.03, 3.19, 7.83, 12.39, 17.47]}, "pc_n_5_12": {"dur": 6.8, "text": "Let's put the recovery session under deadline pressure. Choose the first meeting you'd hold, and you'll hear where it leads.", "sents": [[0, "Let's put the recovery session under deadline pressure.", 0], [3.37, "Choose the first meeting you'd hold, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0, 3.37]}, "pc_n_5_12_o0": {"dur": 11.12, "text": "The plan gets done, and the team learns that finishing hard is followed by starting hard. That's how burnout becomes normal, one meeting at a time. Try the other option to compare.", "sents": [[0.05, "The plan gets done, and the team learns that finishing hard is followed by starting hard.", 0], [5.81, "That's how burnout becomes normal, one meeting at a time.", 0], [9.43, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_5_12_o1": {"dur": 8.24, "text": "The plan still gets done by Friday. It's written by a team that believes recovery is real, because they just watched you make time for it.", "sents": [[0.05, "The plan still gets done by Friday.", 0], [2.71, "It's written by a team that believes recovery is real, because they just watched you make time for it.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_5_14": {"dur": 30.48, "text": "Your core rep this week is your energy audit, about fifteen minutes. Track your energy for one day, note what drained you and what fueled you, then protect one block on next week's calendar. If you have more time, choose one practice your team will see you keep, and write the sentence you'll use to name it. And plan the recovery session for after your next big deadline: wins, lessons and what you'll give back. Run your core rep, then ask one person how it landed. Select Open your Lesson 5 pages to get started.", "sents": [[0.01, "Your core rep this week is your energy audit, about fifteen minutes.", 0], [4.35, "Track your energy for one day, note what drained you and what fueled you, then protect one block on next week's calendar.", 0], [11.41, "If you have more time, choose one practice your team will see you keep, and write the sentence you'll use to name it.", 1], [17.55, "And plan the recovery session for after your next big deadline: wins, lessons and what you'll give back.", 2], [24.41, "Run your core rep, then ask one person how it landed.", 3], [27.09, "Select Open your Lesson 5 pages to get started.", 3]], "v": "r3", "cues": [0.01, 11.41, 17.55, 24.41]}, "pc_n_5_15": {"dur": 12.88, "text": "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst. She's a professional athlete and the founder of RyFit International, and she looks at performance through the whole of your life. Press play to hear from her.", "sents": [[0.01, "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst.", 0], [4.73, "She's a professional athlete and the founder of RyFit International, and she looks at performance through the whole of your life.", 1], [11.53, "Press play to hear from her.", 1]], "v": "r3", "cues": [0.01, 4.73]}, "pc_n_5_16": {"dur": 12.4, "text": "Ryall's drill checks whether your pace is sustainable. It takes three minutes. Select Start the timer and work through each step. When you're done, or once you've planned when you'll run it, tick the box that fits.", "sents": [[0, "Ryall's drill checks whether your pace is sustainable.", 0], [3.19, "It takes three minutes.", 0], [4.75, "Select Start the timer and work through each step.", 1], [8.03, "When you're done, or once you've planned when you'll run it, tick the box that fits.", 1]], "v": "r3", "cues": [0, 4.75]}, "pc_n_5_18_q0": {"dur": 7.84, "text": "A few questions on the main ideas. First: which of these is modeling a sustainable practice, rather than announcing one?", "sents": [[0, "A few questions on the main ideas.", 0], [2.25, "First: which of these is modeling a sustainable practice, rather than announcing one?", 0]], "v": "r3", "cues": [0]}, "pc_n_5_18_w0": {"dur": 9.68, "text": "Your team copies what you do. When they see you keep a practice and hear why, it becomes permission. Words alone get canceled by the late-night email.", "sents": [[0.05, "Your team copies what you do.", 0], [2.43, "When they see you keep a practice and hear why, it becomes permission.", 0], [6.71, "Words alone get canceled by the late-night email.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_5_18_q1": {"dur": 3.76, "text": "What does managing energy, rather than time, look like?", "sents": [[0.05, "What does managing energy, rather than time, look like?", 0]], "v": "r3", "cues": [0.05]}, "pc_n_5_18_w1": {"dur": 8.16, "text": "You schedule your hardest work for your best hours and build recovery in, like the executive with ninety minutes of deep work and two short breaks.", "sents": [[0, "You schedule your hardest work for your best hours and build recovery in, like the executive with ninety minutes of deep work and two short breaks.", 0]], "v": "r3", "cues": [0]}, "pc_n_5_18_q2": {"dur": 3.12, "text": "After a brutal quarter, what comes first?", "sents": [[0, "After a brutal quarter, what comes first?", 0]], "v": "r3", "cues": [0]}, "pc_n_5_18_w2": {"dur": 8.32, "text": "Celebrate, capture the lessons and give something back, then plan. The order shows the team that recovery is real.", "sents": [[0.05, "Celebrate, capture the lessons and give something back, then plan.", 0], [5.13, "The order shows the team that recovery is real.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_5_18_q3": {"dur": 7.28, "text": "Last one. Your star player works constantly and you're worried about burnout. What's the best opening?", "sents": [[0.15, "Last one.", 0], [1.35, "Your star player works constantly and you're worried about burnout.", 0], [5.91, "What's the best opening?", 0]], "v": "r3", "cues": [0.15]}, "pc_n_5_18_w3": {"dur": 7.2, "text": "Recognizing their dedication keeps it safe to talk about. Asking how they'll sustain it makes them part of the solution.", "sents": [[0.03, "Recognizing their dedication keeps it safe to talk about.", 0], [3.87, "Asking how they'll sustain it makes them part of the solution.", 0]], "v": "r3", "cues": [0.03]}, "pc_n_5_19": {"dur": 30.24, "text": "Before you go, here's what to keep from this lesson. Protect your best hours. One deep-work block and one recovery block on the calendar is a good start. Your team copies what you do, so pick one practice they'll see you keep, and say why. And after a hard stretch, recover first: wins, lessons, something back. Then plan. Select Download my answers for a Word copy of what you wrote today. Chapter 10 of the book is about sustaining your energy.", "sents": [[0.03, "Before you go, here's what to keep from this lesson.", 0], [3.81, "Protect your best hours.", 1], [5.67, "One deep-work block and one recovery block on the calendar is a good start.", 1], [10.49, "Your team copies what you do, so pick one practice they'll see you keep, and say why.", 2], [15.99, "And after a hard stretch, recover first: wins, lessons, something back.", 3], [21.51, "Then plan.", 3], [23.03, "Select Download my answers for a Word copy of what you wrote today.", 4], [26.61, "Chapter 10 of the book is about sustaining your energy.", 4]], "v": "r3", "cues": [0.03, 3.81, 10.49, 15.99, 23.03]}, "pc_n_5_20": {"dur": 17.2, "text": "That's Lesson 5 done. One lesson to go, and the championship round is next. This week, run your core rep, your energy audit, and ask one person how it landed. Next time is the last lesson, and the conversation that makes your Athleader's season visible. It's the big one.", "sents": [[0.05, "That's Lesson 5 done.", 0], [1.87, "One lesson to go, and the championship round is next.", 0], [5.41, "This week, run your core rep, your energy audit, and ask one person how it landed.", 1], [10.63, "Next time is the last lesson, and the conversation that makes your Athleader's season visible.", 1], [16.09, "It's the big one.", 1]], "v": "r3", "cues": [0.05, 5.41]}, "pc_n_6_0": {"dur": 13.68, "text": "Lesson 6 is the victory lap, and the big moment of your season as a Player-Coach. You'll decide which habits to keep, and hold the conversation that celebrates your Athleader's season and sets up the next one. Select Start lesson.", "sents": [[0.01, "Lesson 6 is the victory lap, and the big moment of your season as a Player-Coach.", 0], [5.51, "You'll decide which habits to keep, and hold the conversation that celebrates your Athleader's season and sets up the next one.", 1], [12.39, "Select Start lesson.", 1]], "v": "r3", "cues": [0.01, 5.51]}, "pc_n_6_1": {"dur": 20.8, "text": "Read this moment, and think about how most seasons end. A quiet well done wastes a season's work. Think back over the season: what have you seen your Athleader do differently? You'll both be asked about it at the end. This lesson is one conversation with three parts, and one decision about which of your own new habits you'll keep.", "sents": [[0.05, "Read this moment, and think about how most seasons end.", 0], [4.31, "A quiet well done wastes a season's work.", 1], [7.65, "Think back over the season: what have you seen your Athleader do differently?", 1], [12.01, "You'll both be asked about it at the end.", 1], [14.31, "This lesson is one conversation with three parts, and one decision about which of your own new habits you'll keep.", 1]], "v": "r3", "cues": [0.05, 4.31]}, "pc_n_6_3": {"dur": 6.24, "text": "A quick look back at Lesson 5 before you start. Choose the answer you remember. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 5 before you start.", 0], [3.03, "Choose the answer you remember.", 1], [4.77, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 3.03]}, "pc_n_6_4": {"dur": 32.0, "text": "Here's what you'll practice in this lesson. You'll choose one or two habits from this season and give them a place on your calendar, so they last after the experience ends. You'll celebrate your Athleader's work in a way that fits them. Some people want public praise, and others would rather hear it privately. You'll make sure someone above you hears what they did. It's the part of coaching only you can do. And you'll close the season with one question about the next ninety days. Then you'll take the post-assessment, which ends with a few questions about your Athleader.", "sents": [[0.01, "Here's what you'll practice in this lesson.", 0], [2.33, "You'll choose one or two habits from this season and give them a place on your calendar, so they last after the experience ends.", 1], [9.79, "You'll celebrate your Athleader's work in a way that fits them.", 2], [13.21, "Some people want public praise, and others would rather hear it privately.", 2], [17.45, "You'll make sure someone above you hears what they did.", 3], [20.55, "It's the part of coaching only you can do.", 3], [23.13, "And you'll close the season with one question about the next ninety days.", 4], [27.51, "Then you'll take the post-assessment, which ends with a few questions about your Athleader.", 4]], "v": "r3", "cues": [0.01, 2.33, 9.79, 17.45, 23.13]}, "pc_n_6_7": {"dur": 25.2, "text": "Look back at what you've tried this season. Your first move under pressure, the feedback steps, the one-goal check-in, schedule-send, recovery before planning. Pick one or two to keep. A practice lasts when it has a recurring slot, a clear trigger and someone who'd notice if you stopped. The manager in the video replaced drive-by feedback with a short feedback session every Friday, and it stuck because it was on his calendar.", "sents": [[0.07, "Look back at what you've tried this season.", 0], [2.47, "Your first move under pressure, the feedback steps, the one-goal check-in, schedule-send, recovery before planning.", 0], [9.73, "Pick one or two to keep.", 1], [11.45, "A practice lasts when it has a recurring slot, a clear trigger and someone who'd notice if you stopped.", 1], [17.77, "The manager in the video replaced drive-by feedback with a short feedback session every Friday, and it stuck because it was on his calendar.", 1]], "v": "r3", "cues": [0.07, 9.73]}, "pc_n_6_9": {"dur": 33.68, "text": "This is your last play call of the season, and it has three parts. First, celebrate. Name a specific project where they used what they learned, and do it in the way they like to be recognized, publicly or privately. Second, provide visibility. Book fifteen minutes with your own leader, with your Athleader there, and say what they did. They can't create that kind of visibility for themselves. Third, plan the next season. Ask what their focus will be for the next ninety days, and write the answer down. It's your coaching agenda for next quarter.", "sents": [[0.01, "This is your last play call of the season, and it has three parts.", 0], [4.27, "First, celebrate.", 1], [6.33, "Name a specific project where they used what they learned, and do it in the way they like to be recognized, publicly or privately.", 1], [13.85, "Second, provide visibility.", 2], [16.51, "Book fifteen minutes with your own leader, with your Athleader there, and say what they did.", 2], [21.51, "They can't create that kind of visibility for themselves.", 2], [24.79, "Third, plan the next season.", 3], [27.53, "Ask what their focus will be for the next ninety days, and write the answer down.", 3], [31.59, "It's your coaching agenda for next quarter.", 3]], "v": "r3", "cues": [0.01, 4.27, 13.85, 24.79]}, "pc_n_6_10": {"dur": 24.56, "text": "Here's the example from the video. Sarah finished the experience and put it to work on a real project. Her manager sent a team-wide note naming that project. Then she booked fifteen minutes with her own boss, with Sarah there. She said one sentence: I want you to hear about the great work Sarah is doing. That's visibility Sarah couldn't have created for herself, and it cost her manager fifteen minutes.", "sents": [[0.01, "Here's the example from the video.", 0], [2.15, "Sarah finished the experience and put it to work on a real project.", 1], [6.41, "Her manager sent a team-wide note naming that project.", 2], [9.75, "Then she booked fifteen minutes with her own boss, with Sarah there.", 2], [13.75, "She said one sentence: I want you to hear about the great work Sarah is doing.", 3], [18.83, "That's visibility Sarah couldn't have created for herself, and it cost her manager fifteen minutes.", 4]], "v": "r3", "cues": [0.01, 2.15, 6.41, 13.75, 18.83]}, "pc_n_6_12": {"dur": 15.92, "text": "In Lesson 1, Melissa asked you to name one leadership behavior you wanted to strengthen. Here's what you wrote. Now write how you've made progress on it, with one specific moment from this season. A named moment tells you what actually changed. Then select Next.", "sents": [[0, "In Lesson 1, Melissa asked you to name one leadership behavior you wanted to strengthen.", 0], [5.47, "Here's what you wrote.", 0], [6.83, "Now write how you've made progress on it, with one specific moment from this season.", 1], [11.57, "A named moment tells you what actually changed.", 1], [14.89, "Then select Next.", 2]], "v": "r3", "cues": [0, 6.83, 14.89]}, "pc_n_6_13": {"dur": 6.88, "text": "One last call for the season. Your Athleader is wrapping up. Pick your last question, and you'll hear where it leads.", "sents": [[0, "One last call for the season.", 0], [2.13, "Your Athleader is wrapping up.", 1], [4.13, "Pick your last question, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0, 2.13]}, "pc_n_6_13_o0": {"dur": 8.96, "text": "It's kind, and it closes the season. Their next quarter will probably look exactly like the last one. Try the other option to compare.", "sents": [[0.07, "It's kind, and it closes the season.", 0], [3.37, "Their next quarter will probably look exactly like the last one.", 0], [7.11, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.07]}, "pc_n_6_13_o1": {"dur": 6.8, "text": "That question treats the finish as a starting point, and their answer gives you your coaching agenda for next quarter.", "sents": [[0.05, "That question treats the finish as a starting point, and their answer gives you your coaching agenda for next quarter.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_6_15": {"dur": 26.24, "text": "Your core rep this week is the Championship Conversation: celebrate, provide visibility, and ask about the next ninety days. If you have more time, choose one or two habits to keep, and for each one write the recurring slot, the trigger and the person who'd notice if you stopped. Your post-assessment comes at the end of this lesson. Run your core rep, then ask your Athleader how it landed. Select Open your Lesson 6 pages to get started.", "sents": [[0.01, "Your core rep this week is the Championship Conversation: celebrate, provide visibility, and ask about the next ninety days.", 0], [8.21, "If you have more time, choose one or two habits to keep, and for each one write the recurring slot, the trigger and the person who'd notice if you stopped.", 1], [17.17, "Your post-assessment comes at the end of this lesson.", 2], [19.99, "Run your core rep, then ask your Athleader how it landed.", 3], [23.33, "Select Open your Lesson 6 pages to get started.", 3]], "v": "r3", "cues": [0.01, 8.21, 17.17, 19.99]}, "pc_n_6_16": {"dur": 13.44, "text": "This lesson's Athleader Pro is Sagar Pandya, the AI Integrator. He works on bringing people and technology into line around a shared purpose, and his drill is one you run with your team. Press play to hear from him.", "sents": [[0, "This lesson's Athleader Pro is Sagar Pandya, the AI Integrator.", 0], [4.89, "He works on bringing people and technology into line around a shared purpose, and his drill is one you run with your team.", 1], [12.07, "Press play to hear from him.", 1]], "v": "r3", "cues": [0, 4.89]}, "pc_n_6_17": {"dur": 13.92, "text": "Sagar's drill aligns your team on one mission, and it takes about fifteen minutes with your team. Select Start the timer and take the team through each step. When you've run it, or once you've planned when you will, tick the box that fits.", "sents": [[0, "Sagar's drill aligns your team on one mission, and it takes about fifteen minutes with your team.", 0], [5.67, "Select Start the timer and take the team through each step.", 1], [9.57, "When you've run it, or once you've planned when you will, tick the box that fits.", 1]], "v": "r3", "cues": [0, 5.67]}, "pc_n_6_19_q0": {"dur": 6.72, "text": "A few questions on the main ideas. First: what does provide visibility mean in the Championship Conversation?", "sents": [[0, "A few questions on the main ideas.", 0], [2.19, "First: what does provide visibility mean in the Championship Conversation?", 0]], "v": "r3", "cues": [0]}, "pc_n_6_19_w0": {"dur": 6.56, "text": "It's advocacy. You make sure senior people hear about their work, which they can't do for themselves.", "sents": [[0.05, "It's advocacy.", 0], [1.67, "You make sure senior people hear about their work, which they can't do for themselves.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_6_19_q1": {"dur": 4.08, "text": "What makes a new leadership practice last after this experience?", "sents": [[0.05, "What makes a new leadership practice last after this experience?", 0]], "v": "r3", "cues": [0.05]}, "pc_n_6_19_w1": {"dur": 8.8, "text": "Intentions fade in a few months. A recurring slot, a clear trigger and someone who'd notice keep the habit going, like the Friday feedback session.", "sents": [[0.05, "Intentions fade in a few months.", 0], [2.43, "A recurring slot, a clear trigger and someone who'd notice keep the habit going, like the Friday feedback session.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_6_19_q2": {"dur": 4.24, "text": "Your Athleader dislikes public praise. How do you celebrate them?", "sents": [[0.05, "Your Athleader dislikes public praise.", 0], [2.91, "How do you celebrate them?", 0]], "v": "r3", "cues": [0.05]}, "pc_n_6_19_w2": {"dur": 8.72, "text": "Recognition only works when it fits the person. Ask how they like to be recognized, and still make sure the right people hear about their work.", "sents": [[0.05, "Recognition only works when it fits the person.", 0], [3.53, "Ask how they like to be recognized, and still make sure the right people hear about their work.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_6_19_q3": {"dur": 4.64, "text": "Last one. Why end the season by asking about the next ninety days?", "sents": [[0.03, "Last one.", 0], [1.33, "Why end the season by asking about the next ninety days?", 0]], "v": "r3", "cues": [0.03]}, "pc_n_6_19_w3": {"dur": 6.16, "text": "It frames what they've built as a foundation, and their answer becomes your coaching agenda for next quarter.", "sents": [[0, "It frames what they've built as a foundation, and their answer becomes your coaching agenda for next quarter.", 0]], "v": "r3", "cues": [0]}, "pc_n_6_20": {"dur": 30.56, "text": "Before you finish, a quick recap. Keep one or two habits from this season, and give them a slot on your calendar and someone who'd notice. The Championship Conversation has three parts: celebrate, provide visibility and plan the next season. The middle one is the part only you can do. And ask about the next ninety days. The answer is your coaching agenda. Select Download my answers for a Word copy of what you wrote today. Chapter 12 of the book is about becoming the Player-Coach.", "sents": [[0.03, "Before you finish, a quick recap.", 0], [2.49, "Keep one or two habits from this season, and give them a slot on your calendar and someone who'd notice.", 1], [8.49, "The Championship Conversation has three parts: celebrate, provide visibility and plan the next season.", 2], [15.49, "The middle one is the part only you can do.", 2], [18.33, "And ask about the next ninety days.", 3], [20.77, "The answer is your coaching agenda.", 3], [23.13, "Select Download my answers for a Word copy of what you wrote today.", 4], [26.57, "Chapter 12 of the book is about becoming the Player-Coach.", 4]], "v": "r3", "cues": [0.03, 2.49, 8.49, 18.33, 23.13]}, "pc_n_E2": {"dur": 4.64, "text": "Type the code from the last page of the post-assessment, then select Submit.", "sents": [[0.05, "Type the code from the last page of the post-assessment, then select Submit.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_E4": {"dur": 15.12, "text": "You should be proud of what you've built this season, for yourself and for your team. Share it. Copy the post, open LinkedIn, and add the certificate you just downloaded. You might be the reason another leader steps into the Arena. This step is optional.", "sents": [[0.03, "You should be proud of what you've built this season, for yourself and for your team.", 0], [4.79, "Share it.", 0], [5.65, "Copy the post, open LinkedIn, and add the certificate you just downloaded.", 1], [10.33, "You might be the reason another leader steps into the Arena.", 1], [13.75, "This step is optional.", 1]], "v": "r3", "cues": [0.03, 5.65]}, "r2_form_pre": {"dur": 16.24, "text": "Take your time with these. There are no right answers, and your individual answers stay confidential. You can go back and change answers until you submit. When you submit, a short code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0.01, "Take your time with these.", 0], [1.75, "There are no right answers, and your individual answers stay confidential.", 0], [6.27, "You can go back and change answers until you submit.", 0], [9.49, "When you submit, a short code appears on the last page.", 0], [12.95, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0.01]}, "r2_code_pulse": {"dur": 5.84, "text": "Type the code from the last page of the Pulse Check, then select Submit. That completes the lesson.", "sents": [[0.03, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.37, "That completes the lesson.", 0]], "v": "r3", "cues": [0.03]}, "r2_pc_E1": {"dur": 16.08, "text": "You've finished all six lessons. The last step is your post-assessment: the same questions you answered before Lesson 1, then a few about the Athleader you've been coaching. It takes about eight minutes, and your Growth Guide comes with your results. Select Next and it opens right here.", "sents": [[0.01, "You've finished all six lessons.", 0], [2.49, "The last step is your post-assessment: the same questions you answered before Lesson 1, then a few about the Athleader you've been coaching.", 0], [10.19, "It takes about eight minutes, and your Growth Guide comes with your results.", 1], [13.79, "Select Next and it opens right here.", 1]], "v": "r3", "cues": [0.01, 10.19]}, "r2_form_post": {"dur": 10.56, "text": "Answer for where you are now, not where you started. When you submit, your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer for where you are now, not where you started.", 0], [3.65, "When you submit, your code appears on the last page.", 0], [7.17, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_pulse": {"dur": 23.52, "text": "Every lesson ends with the same short Pulse Check, your check-in after every lesson, so you can see how you're changing over the season. It asks how often, in the last two weeks, you've practiced each of the Core 4, and whether you did this lesson's reps. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next and it opens right here.", "sents": [[0.05, "Every lesson ends with the same short Pulse Check, your check-in after every lesson, so you can see how you're changing over the season.", 0], [7.75, "It asks how often, in the last two weeks, you've practiced each of the Core 4, and whether you did this lesson's reps.", 1], [14.75, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [21.33, "Select Next and it opens right here.", 2]], "v": "r3", "cues": [0.05, 7.75, 14.75]}, "r2_code_pre": {"dur": 14.72, "text": "Type the code from the last page of the assessment, then select Submit. Lesson 1 opens as soon as the code is accepted. Your Growth Guide comes with your results. Keep it somewhere safe, because at the end of your season you'll compare it with your final results.", "sents": [[0.03, "Type the code from the last page of the assessment, then select Submit.", 0], [4.31, "Lesson 1 opens as soon as the code is accepted.", 0], [7.49, "Your Growth Guide comes with your results.", 1], [9.75, "Keep it somewhere safe, because at the end of your season you'll compare it with your final results.", 1]], "v": "r3", "cues": [0.03, 7.49]}, "r2_pc_G6": {"dur": 30.0, "text": "This is your Benchmark Pre-Assessment, your starting point as a leader. It asks how you lead yourself and your team today, and at the end of your season you'll take the same assessment, so you can see what changed. It takes about ten minutes, and your individual answers stay confidential. You need to finish it to open Lesson 1. Select Next when you're ready, and it opens right here. With your results, you'll receive your Growth Guide: where you stand today, and what to work on first. Keep it somewhere safe for the end of your season.", "sents": [[0, "This is your Benchmark Pre-Assessment, your starting point as a leader.", 0], [4.41, "It asks how you lead yourself and your team today, and at the end of your season you'll take the same assessment, so you can see what changed.", 0], [12.01, "It takes about ten minutes, and your individual answers stay confidential.", 1], [16.31, "You need to finish it to open Lesson 1.", 1], [18.75, "Select Next when you're ready, and it opens right here.", 1], [22.09, "With your results, you'll receive your Growth Guide: where you stand today, and what to work on first.", 2], [27.19, "Keep it somewhere safe for the end of your season.", 2]], "v": "r3", "cues": [0, 12.01, 22.09]}, "r2_cert": {"dur": 16.16, "text": "Congratulations. You've completed the M.V.P. Accelerator, and this certificate is yours. You earned it. Type your name the way you want it printed, then select Download my certificate. It saves as a PDF you can print, keep, and share on the next screen.", "sents": [[0.01, "Congratulations.", 0], [1.41, "You've completed the M.V.P. Accelerator, and this certificate is yours.", 0], [6.21, "You earned it.", 0], [7.41, "Type your name the way you want it printed, then select Download my certificate.", 1], [12.01, "It saves as a PDF you can print, keep, and share on the next screen.", 1]], "v": "r3", "cues": [0.01, 7.41]}, "r2_form_wall": {"dur": 24.56, "text": "Before you go, pay it forward. The Wall of Fame is where each group leaves something for the next one. Share one moment from your season that showed you what had changed. We're in this together, and your words help the next group step into the Arena. If you'd like to stay connected to the Athleadership community, select the button for podcasts, newsletters and events. Both steps are optional, and when you're done, you can close the course.", "sents": [[0.03, "Before you go, pay it forward.", 0], [2.55, "The Wall of Fame is where each group leaves something for the next one.", 0], [6.29, "Share one moment from your season that showed you what had changed.", 1], [10.25, "We're in this together, and your words help the next group step into the Arena.", 1], [14.63, "If you'd like to stay connected to the Athleadership community, select the button for podcasts, newsletters and events.", 2], [21.19, "Both steps are optional, and when you're done, you can close the course.", 2]], "v": "r3", "cues": [0.03, 6.29, 14.63]}, "ci_a": {"dur": 21.28, "text": "Pressure shows how you actually lead, and this is where you start to see the gap between instinct and intention. Take about thirty seconds on each of these. Write what actually went on in you, rather than what you think should have. Only you can see this, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead, and this is where you start to see the gap between instinct and intention.", 0], [7.23, "Take about thirty seconds on each of these.", 1], [9.83, "Write what actually went on in you, rather than what you think should have.", 1], [13.89, "Only you can see this, and it's saved here so you can come back to it.", 1], [17.83, "Select Save on each one as you go, then select Next.", 2]], "v": "r3", "cues": [0.03, 7.23, 17.83]}, "ci_b": {"dur": 9.68, "text": "Now look at what you wrote, and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the honest one.", "sents": [[0.09, "Now look at what you wrote, and pick the pattern that's closest to it.", 0], [3.97, "There's no right answer.", 1], [5.45, "Naming a habit helps you catch it sooner next time, so pick the honest one.", 1]], "v": "r3", "cues": [0.09, 3.97]}, "ci_c": {"dur": 17.2, "text": "Now run the Foundation Reset. Say your five words, the ones you wrote in Lesson 1. Ask yourself for two next-best steps, and pick the one you'll do in the next ten minutes. Then take one breath. It takes about a minute and works best standing up, so do it now, before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.23, "Say your five words, the ones you wrote in Lesson 1.", 1], [5.51, "Ask yourself for two next-best steps, and pick the one you'll do in the next ten minutes.", 1], [10.75, "Then take one breath.", 1], [12.61, "It takes about a minute and works best standing up, so do it now, before you move on.", 2]], "v": "r3", "cues": [0, 2.23, 12.61]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "r3", "cues": [0.05]}, "n_1_3": {"dur": 12.88, "text": "Before any coaching, take one clean read of how you react. This drill is short. Press play. Melissa will stop partway through and ask what you notice. Type your answer, and the video carries on.", "sents": [[0.03, "Before any coaching, take one clean read of how you react.", 0], [4.65, "This drill is short.", 0], [5.97, "Press play.", 1], [7.05, "Melissa will stop partway through and ask what you notice.", 1], [10.57, "Type your answer, and the video carries on.", 1]], "v": "r3", "cues": [0.03, 5.97]}, "n_1_8_agility": {"dur": 12.24, "text": "When agility is conditioned, you don't need certainty to move. You make the call and adjust as things change. When it isn't, you wait for certainty while everything keeps changing around you.", "sents": [[0.01, "When agility is conditioned, you don't need certainty to move.", 0], [4.43, "You make the call and adjust as things change.", 0], [7.55, "When it isn't, you wait for certainty while everything keeps changing around you.", 1]], "v": "r3", "cues": [0.01, 7.55]}, "n_1_8_alignment": {"dur": 11.84, "text": "When alignment is conditioned, you know what matters most. You make the hard call and keep people moving in the same direction. When it isn't, everything feels urgent and people pull different ways.", "sents": [[0.07, "When alignment is conditioned, you know what matters most.", 0], [3.87, "You make the hard call and keep people moving in the same direction.", 0], [7.65, "When it isn't, everything feels urgent and people pull different ways.", 1]], "v": "r3", "cues": [0.07, 7.65]}, "n_1_8_resilience": {"dur": 10.24, "text": "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play. When it isn't, one hard moment follows you into the next one.", "sents": [[0.07, "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play.", 0], [6.47, "When it isn't, one hard moment follows you into the next one.", 1]], "v": "r3", "cues": [0.07, 6.47]}, "n_1_8_wellbeing": {"dur": 12.08, "text": "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises. When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", "sents": [[0.01, "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises.", 0], [7.77, "When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", 1]], "v": "r3", "cues": [0.01, 7.77]}, "n_1_R": {"dur": 49.92, "text": "Before your first Moment, here's one tool you'll use all season. It's called the Foundation Reset, and it comes from Melissa's book. Under pressure, your brain's alarm, the amygdala, fires faster than the part that plans, the prefrontal cortex. Your five words tell the alarm to stand down, and bring your thinking brain back online. Melissa used it in a hotel hallway, two days before her biggest summit, as the world shut down. Five words: I'm not in danger, deciding. Two options: cancel or pivot? One default: we pivot, now. Thirty-eight hours later, one of the first global virtual leadership events went live. Now write your own five words. Use one of Melissa's to start, or write words that would steady you. Select Save, and you'll see them again in every check-in.", "sents": [[0.03, "Before your first Moment, here's one tool you'll use all season.", 0], [4.39, "It's called the Foundation Reset, and it comes from Melissa's book.", 0], [8.29, "Under pressure, your brain's alarm, the amygdala, fires faster than the part that plans, the prefrontal cortex.", 1], [15.43, "Your five words tell the alarm to stand down, and bring your thinking brain back online.", 1], [20.53, "Melissa used it in a hotel hallway, two days before her biggest summit, as the world shut down.", 2], [26.49, "Five words: I'm not in danger, deciding.", 2], [30.13, "Two options: cancel or pivot?", 2], [32.95, "One default: we pivot, now.", 2], [34.15, "Thirty-eight hours later, one of the first global virtual leadership events went live.", 2], [41.29, "Now write your own five words.", 3], [43.11, "Use one of Melissa's to start, or write words that would steady you.", 3], [46.79, "Select Save, and you'll see them again in every check-in.", 3]], "v": "r3", "cues": [0.03, 8.29, 20.53, 41.29]}, "n_2_15": {"dur": 10.4, "text": "Time for the drill. It puts you under a little pressure and asks you to respond. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0, "Time for the drill.", 0], [1.53, "It puts you under a little pressure and asks you to respond.", 0], [5.23, "Press play.", 1], [6.19, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "v": "r3", "cues": [0, 5.23]}, "n_3_15": {"dur": 14.48, "text": "Time for the drill. This one tests how much certainty you need before you move. Press play. Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision. Answer each time, and the video carries on.", "sents": [[0, "Time for the drill.", 0], [1.33, "This one tests how much certainty you need before you move.", 0], [5.13, "Press play.", 1], [6.19, "Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision.", 1], [12.01, "Answer each time, and the video carries on.", 1]], "v": "r3", "cues": [0, 5.13]}, "n_4_14": {"dur": 10.88, "text": "Time for the drill. This one is about how quickly you recover when something goes wrong. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.45, "This one is about how quickly you recover when something goes wrong.", 0], [5.63, "Press play.", 1], [6.57, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "v": "r3", "cues": [0.01, 5.63]}, "n_5_14": {"dur": 10.48, "text": "Time for the drill. This one puts you in a disagreement, in front of other people. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.47, "This one puts you in a disagreement, in front of other people.", 0], [5.35, "Press play.", 1], [6.35, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "v": "r3", "cues": [0.01, 5.35]}, "n_6_14": {"dur": 12.32, "text": "Time for the last drill of the season. Everything you've practiced arrives at once. Press play. Melissa will stop three times and ask you something. Take the time you need, and the video carries on when you're done.", "sents": [[0.03, "Time for the last drill of the season.", 0], [2.47, "Everything you've practiced arrives at once.", 0], [5.15, "Press play.", 1], [6.19, "Melissa will stop three times and ask you something.", 1], [9.21, "Take the time you need, and the video carries on when you're done.", 1]], "v": "r3", "cues": [0.03, 5.15]}, "n_G2": {"dur": 20.48, "text": "Before you meet your Head Coach, here's an idea to keep with you all season. Performance is not determined by what you know. It is determined by what you can summon under pressure. That's Dr. Michael Platt, who directs the Wharton Neuroscience Initiative and wrote the foreword to Melissa's book. When you're ready, select Meet your Head Coach.", "sents": [[0, "Before you meet your Head Coach, here's an idea to keep with you all season.", 0], [5.23, "Performance is not determined by what you know.", 1], [7.99, "It is determined by what you can summon under pressure.", 1], [11.33, "That's Dr. Michael Platt, who directs the Wharton Neuroscience Initiative and wrote the foreword to Melissa's book.", 2], [17.63, "When you're ready, select Meet your Head Coach.", 3]], "v": "r3", "cues": [0, 5.23, 11.33, 17.63]}, "n_G4": {"dur": 8.16, "text": "Here's a short message from a leader at your organization, about why it chose this season for its leaders. Watch it through before you move on.", "sents": [[0.03, "Here's a short message from a leader at your organization, about why it chose this season for its leaders.", 0], [6.43, "Watch it through before you move on.", 0]], "v": "r3", "cues": [0.03]}, "n_G7": {"dur": 39.68, "text": "People often ask about their Player-Coach at this point, so here are the answers. If your manager isn't taking part, that's okay. Your Player-Coach doesn't have to be your direct manager. You might report to more than one manager, or have none taking part at all, so choose a peer, a mentor or a colleague you trust. Whenever you see Player-Coach, think of that person. Only managers your company selects will have access to the manager track. If you manage several people who are taking part, hold one thirty-minute Commitment Meeting with each of them at the start. After that, build the fifteen-minute check-ins into meetings you already have, so there's nothing extra to schedule.", "sents": [[0.03, "People often ask about their Player-Coach at this point, so here are the answers.", 0], [4.85, "If your manager isn't taking part, that's okay.", 1], [8.01, "Your Player-Coach doesn't have to be your direct manager.", 1], [11.13, "You might report to more than one manager, or have none taking part at all, so choose a peer, a mentor or a colleague you trust.", 1], [19.03, "Whenever you see Player-Coach, think of that person.", 1], [22.37, "Only managers your company selects will have access to the manager track.", 1], [26.01, "If you manage several people who are taking part, hold one thirty-minute Commitment Meeting with each of them at the start.", 2], [33.41, "After that, build the fifteen-minute check-ins into meetings you already have, so there's nothing extra to schedule.", 2]], "v": "r3", "cues": [0.03, 4.85, 26.01]}, "n_G8": {"dur": 26.08, "text": "This course is built from Melissa's book, Athleadership: The Elite Athletic Mindset. You don't need to read it to take part. Each lesson names the chapter if you'd like to go further, and the Foundation Reset you'll learn in Lesson 1 comes straight from it. Your 90-Day Way Scorecard is where the season turns into results. You'll fill it in lesson by lesson and track your goals in it week by week. Download it now, and open the example to see what a finished one looks like.", "sents": [[0, "This course is built from Melissa's book, Athleadership: The Elite Athletic Mindset.", 0], [5.31, "You don't need to read it to take part.", 1], [7.33, "Each lesson names the chapter if you'd like to go further, and the Foundation Reset you'll learn in Lesson 1 comes straight from it.", 1], [14.27, "Your 90-Day Way Scorecard is where the season turns into results.", 2], [18.43, "You'll fill it in lesson by lesson and track your goals in it week by week.", 2], [22.49, "Download it now, and open the example to see what a finished one looks like.", 3]], "v": "r3", "cues": [0, 5.31, 14.27, 22.49]}};
